window.BUNDLED_DECKS = {"javafx-gui-architecture-60":{"id":"javafx-gui-architecture-60","title":"JavaFX GUI Architecture & Development Active Recall Deck","desc":"Comprehensive 60-item standardized active recall deck covering JavaFX GUI architecture, scene graph hierarchy, FXML, MVC, responsive layouts, event handling, observable properties, data bindings, and ListView cell factories.","parts":[{"id":1,"title":"Part 1: JavaFX Fundamentals & Application Architecture","desc":"Foundational JavaFX architecture, JDK modular decoupling, hardware graphics acceleration, Scene Graph hierarchy, Stage/Scene roles, application lifecycle (start/launch), FXML declarative views, and JPMS compilation flags. (Questions 1–15)","range":[1,15]},{"id":2,"title":"Part 2: Layout Management & Container Hierarchy","desc":"Responsive layout design principles, Pane coordinate positioning, USE_COMPUTED_SIZE behavior, VBox vertical ordering and spacing, BorderPane 5-region geometry, GridPane cell mapping and spanning, TitledPane, FlowPane, StackPane, and SplitPane dividers. (Questions 16–30)","range":[16,30]},{"id":3,"title":"Part 3: Event-Driven Programming & Interactive Controls","desc":"Event-driven asynchronous paradigms, ActionEvent dispatching, @FXML controller method signatures, ToggleGroup exclusivity, UserData attachment, continuous MouseEvent handling, and dynamic scene graph mutation (drawing canvas and undo operations). (Questions 31–40)","range":[31,40]},{"id":4,"title":"Part 4: Properties, ChangeListeners, Binding & MVC","desc":"JavaFX reactive property patterns, ChangeListener SAM interfaces, lambda implementations, defensive input validation (requestFocus, selectAll), MVC architectural boundaries, property naming conventions, final accessor design, and unidirectional format bindings. (Questions 41–52)","range":[41,52]},{"id":5,"title":"Part 5: Advanced Controls, Collections, ListCell Rendering & Dialogs","desc":"ObservableList factory methods, collection change observation, ListView selection models, custom ListCell rendering (updateItem), view recycling optimization, null defensive handling, and modal FileChooser dialog management. (Questions 53–60)","range":[53,60]}],"questions":[{"id":1,"partId":1,"partTitle":"Part 1: JavaFX Fundamentals & Application Architecture","prompt":"What was the primary motivation for decoupling JavaFX from the standard Java Development Kit (JDK) starting with Java 11?","code":null,"choices":[{"letter":"A","text":"JavaFX was completely deprecated and replaced by Swing as the default GUI framework."},{"letter":"B","text":"JavaFX was redesigned as an independent, open-source project that evolves in parallel with the JDK."},{"letter":"C","text":"JavaFX required native C++ compilation and could no longer run on JVM bytecode."},{"letter":"D","text":"JavaFX was restricted exclusively to mobile and embedded architectures."}],"answer":"B","answerText":"JavaFX was redesigned as an independent, open-source project that evolves in parallel with the JDK.","explanation":"Decoupling JavaFX into an independent OpenJFX project allowed it to have a faster release cycle and modular architecture independent of JDK releases, rather than bloating the base runtime."},{"id":2,"partId":1,"partTitle":"Part 1: JavaFX Fundamentals & Application Architecture","prompt":"Compared to Swing, JavaFX provides a unified client application platform because it:","code":null,"choices":[{"letter":"A","text":"Replaces all object-oriented syntax with procedural scripting files."},{"letter":"B","text":"Uses separate, disconnected APIs for audio, video, graphics, and UI components."},{"letter":"C","text":"Consolidates GUI controls, 2D/3D graphics, and multimedia (audio/video) into a single API."},{"letter":"D","text":"Prohibits the use of Cascading Style Sheets (CSS) for interface styling."}],"answer":"C","answerText":"Consolidates GUI controls, 2D/3D graphics, and multimedia (audio/video) into a single API.","explanation":"JavaFX unifies GUI components, modern 2D/3D graphics rendering, web views, and multimedia (audio and video playback) within a single cohesive JavaFX API, eliminating the fragmented libraries of earlier UI toolkits like AWT and Swing."},{"id":3,"partId":1,"partTitle":"Part 1: JavaFX Fundamentals & Application Architecture","prompt":"How does JavaFX achieve high-performance rendering for modern graphical user interfaces?","code":null,"choices":[{"letter":"A","text":"By routing all graphics processing through the operating system's software-only CPU emulator."},{"letter":"B","text":"By utilizing the Graphics Processing Unit (GPU) for hardware-accelerated rendering."},{"letter":"C","text":"By translating every JavaFX component directly into an unmanaged C++ pointer."},{"letter":"D","text":"By eliminating multi-threading and running all tasks on a single synchronous loop."}],"answer":"B","answerText":"By utilizing the Graphics Processing Unit (GPU) for hardware-accelerated rendering.","explanation":"JavaFX employs the Prism rendering engine, which leverages hardware graphics acceleration via Direct3D or OpenGL GPUs to achieve smooth, high-fps UI animations and rendering."},{"id":4,"partId":1,"partTitle":"Part 1: JavaFX Fundamentals & Application Architecture","prompt":"Which class enables developers to embed existing Swing components directly inside a JavaFX application?","code":null,"choices":[{"letter":"A","text":"javafx.embed.swing.JFXPanel"},{"letter":"B","text":"javafx.scene.layout.SwingContainer"},{"letter":"C","text":"javafx.scene.layout.SwingNode"},{"letter":"D","text":"javax.swing.JFXBridge"}],"answer":"C","answerText":"javafx.scene.layout.SwingNode","explanation":"javafx.scene.layout.SwingNode allows embedding Swing components inside JavaFX scene graphs. In contrast, JFXPanel is used for embedding JavaFX content into legacy Swing applications."},{"id":5,"partId":1,"partTitle":"Part 1: JavaFX Fundamentals & Application Architecture","prompt":"What role does FXML serve in JavaFX software engineering?","code":null,"choices":[{"letter":"A","text":"It compiles Java bytecode directly into native machine assembly language."},{"letter":"B","text":"It acts as an XML vocabulary for concisely declaring GUI structure and layout without writing Java code."},{"letter":"C","text":"It defines relational database tables and schemas for the application's persistence layer."},{"letter":"D","text":"It replaces Java controller classes by providing procedural script loops for computational algorithms."}],"answer":"B","answerText":"It acts as an XML vocabulary for concisely declaring GUI structure and layout without writing Java code.","explanation":"FXML is an XML-based declarative markup language used to construct JavaFX scene graphs cleanly separating visual layout structure from procedural controller logic."},{"id":6,"partId":1,"partTitle":"Part 1: JavaFX Fundamentals & Application Architecture","prompt":"In declarative JavaFX GUI development, what is the primary benefit of separating FXML from Java controller classes?","code":null,"choices":[{"letter":"A","text":"It eliminates the need to compile Java source files prior to execution."},{"letter":"B","text":"It separates the presentation interface from program logic, improving testability, maintainability, and debugging."},{"letter":"C","text":"It allows JavaFX applications to execute without a Java Virtual Machine (JVM)."},{"letter":"D","text":"It prevents developers from registering event listeners on visual components."}],"answer":"B","answerText":"It separates the presentation interface from program logic, improving testability, maintainability, and debugging.","explanation":"Separating FXML (View) from Java Controller classes adheres to the MVC architecture, isolating visual presentation from event handling and business logic to enhance testability and maintainability."},{"id":7,"partId":1,"partTitle":"Part 1: JavaFX Fundamentals & Application Architecture","prompt":"Which visual design tool maintained by Gluon allows developers to construct JavaFX GUIs via drag-and-drop live editing?","code":null,"choices":[{"letter":"A","text":"Java Mission Control"},{"letter":"B","text":"VisualVM"},{"letter":"C","text":"Scene Builder"},{"letter":"D","text":"Eclipse WindowBuilder"}],"answer":"C","answerText":"Scene Builder","explanation":"Scene Builder is the visual drag-and-drop layout tool originally created by Oracle and currently maintained by Gluon for designing FXML files without writing XML code manually."},{"id":8,"partId":1,"partTitle":"Part 1: JavaFX Fundamentals & Application Architecture","prompt":"In the JavaFX window architecture metaphor, the top-level operating system window is represented by an instance of which class?","code":null,"choices":[{"letter":"A","text":"javafx.stage.Stage"},{"letter":"B","text":"javafx.scene.Scene"},{"letter":"C","text":"javafx.scene.layout.Pane"},{"letter":"D","text":"javafx.stage.WindowFrame"}],"answer":"A","answerText":"javafx.stage.Stage","explanation":"In JavaFX's theater metaphor, the Stage represents the outer window (managed by the OS), the Scene acts as the container holding the visual content, and Nodes represent individual visual elements."},{"id":9,"partId":1,"partTitle":"Part 1: JavaFX Fundamentals & Application Architecture","prompt":"What is a JavaFX Scene Graph?","code":null,"choices":[{"letter":"A","text":"A relational entity-relationship diagram displaying database foreign keys."},{"letter":"B","text":"A tree data structure composed of visual elements (nodes) such as controls, layouts, and shapes."},{"letter":"C","text":"A linear linked list containing sequential user keyboard events."},{"letter":"D","text":"A directed acyclic graph that records method execution call stacks."}],"answer":"B","answerText":"A tree data structure composed of visual elements (nodes) such as controls, layouts, and shapes.","explanation":"A Scene Graph is a hierarchical tree data structure where each visual element (layouts, shapes, controls) is represented as a Node with a single parent."},{"id":10,"partId":1,"partTitle":"Part 1: JavaFX Fundamentals & Application Architecture","prompt":"Regarding the structural nodes in a JavaFX Scene Graph, which statement is TRUE?","code":null,"choices":[{"letter":"A","text":"Every node in the Scene Graph must have at least two parent nodes."},{"letter":"B","text":"Except for the root node, each node in the Scene Graph has exactly one parent."},{"letter":"C","text":"Leaf nodes in a Scene Graph are strictly prohibited from holding control components."},{"letter":"D","text":"Layout containers can only be placed at the root and cannot be nested inside other containers."}],"answer":"B","answerText":"Except for the root node, each node in the Scene Graph has exactly one parent.","explanation":"Every node in a JavaFX Scene Graph (except the root node) must have exactly one parent node, preserving a strict tree hierarchy with no cycles or multi-parenting."},{"id":11,"partId":1,"partTitle":"Part 1: JavaFX Fundamentals & Application Architecture","prompt":"What is the fundamental entry-point method that every JavaFX application subclass must override?","code":null,"choices":[{"letter":"A","text":"public void main(String[] args)"},{"letter":"B","text":"public void init(Stage stage)"},{"letter":"C","text":"public void start(Stage stage)"},{"letter":"D","text":"public void run(Scene scene)"}],"answer":"C","answerText":"public void start(Stage stage)","explanation":"The start(Stage primaryStage) method is the abstract entry-point method of javafx.application.Application that must be overridden to configure and show the primary stage."},{"id":12,"partId":1,"partTitle":"Part 1: JavaFX Fundamentals & Application Architecture","prompt":"When launching a JavaFX desktop application, what occurs when Application.launch(args) is called from main?","code":null,"choices":[{"letter":"A","text":"It terminates the JVM and spawns an independent C++ process."},{"letter":"B","text":"It initializes the JavaFX runtime, instantiates the Application subclass, and invokes its start method."},{"letter":"C","text":"It bypasses scene graph creation and displays raw FXML markup as text."},{"letter":"D","text":"It creates a headless daemon background service without window decorations."}],"answer":"B","answerText":"It initializes the JavaFX runtime, instantiates the Application subclass, and invokes its start method.","explanation":"Calling Application.launch(args) initializes the JavaFX toolkit runtime, instantiates the specified Application subclass on the JavaFX Application Thread, and invokes its init() and start() methods."},{"id":13,"partId":1,"partTitle":"Part 1: JavaFX Fundamentals & Application Architecture","prompt":"Which static method from FXMLLoader is invoked to parse an FXML document, construct the scene graph, and instantiate its controller?","code":null,"choices":[{"letter":"A","text":"FXMLLoader.parse(URL location)"},{"letter":"B","text":"FXMLLoader.compile(String resourcePath)"},{"letter":"C","text":"FXMLLoader.load(URL location)"},{"letter":"D","text":"FXMLLoader.inflate(InputStream stream)"}],"answer":"C","answerText":"FXMLLoader.load(URL location)","explanation":"FXMLLoader.load(URL location) is the static convenience method that parses the target FXML file, builds the node hierarchy in memory, and wires up its designated controller."},{"id":14,"partId":1,"partTitle":"Part 1: JavaFX Fundamentals & Application Architecture","prompt":"What happens during runtime if an @FXML instance variable name in a controller class does not match the fx:id in the corresponding FXML file?","code":null,"choices":[{"letter":"A","text":"The variable is automatically assigned a default stub instance."},{"letter":"B","text":"The compiler converts the variable to a local static variable."},{"letter":"C","text":"The FXMLLoader throws a LoadException because it cannot inject the reference."},{"letter":"D","text":"The Java runtime terminates without throwing an exception."}],"answer":"C","answerText":"The FXMLLoader throws a LoadException because it cannot inject the reference.","explanation":"If an @FXML annotated field name does not match the fx:id specified in the FXML document, the FXMLLoader cannot inject the scene graph node and throws a LoadException."},{"id":15,"partId":1,"partTitle":"Part 1: JavaFX Fundamentals & Application Architecture","prompt":"When compiling a modular JavaFX application using the Java Platform Module System (JPMS), which two command-line options are mandatory?","code":null,"choices":[{"letter":"A","text":"--classpath and --target-runtime"},{"letter":"B","text":"--module-path and --add-modules"},{"letter":"C","text":"--enable-preview and -sourcepath"},{"letter":"D","text":"--boot-modules and --include-libs"}],"answer":"B","answerText":"--module-path and --add-modules","explanation":"Under the Java Platform Module System (JPMS), non-modular applications or modular builds running JavaFX must specify --module-path pointing to JavaFX SDK jars and --add-modules indicating required modules like javafx.controls and javafx.fxml."},{"id":16,"partId":2,"partTitle":"Part 2: Layout Management & Container Hierarchy","prompt":"Why is it considered best practice to avoid hardcoding explicit pixel dimensions (width and height) for JavaFX GUI nodes?","code":null,"choices":[{"letter":"A","text":"Explicit sizes cause the Java compiler to reject FXML parsing."},{"letter":"B","text":"Hardcoded sizes prevent controls from adapting gracefully when content updates or windows are resized."},{"letter":"C","text":"Scene Builder cannot preview elements that define width and height attributes."},{"letter":"D","text":"Hardcoded pixel coordinates disable hardware-accelerated GPU rendering."}],"answer":"B","answerText":"Hardcoded sizes prevent controls from adapting gracefully when content updates or windows are resized.","explanation":"Hardcoding pixel dimensions prevents GUIs from adapting to varying screen resolutions, DPI scaling, font sizing changes, and dynamic window resizing. Responsive layouts rely on automatic pane computation."},{"id":17,"partId":2,"partTitle":"Part 2: Layout Management & Container Hierarchy","prompt":"Which layout pane in the javafx.scene.layout package positions child nodes at exact coordinates (absolute positioning)?","code":null,"choices":[{"letter":"A","text":"FlowPane"},{"letter":"B","text":"GridPane"},{"letter":"C","text":"Pane"},{"letter":"D","text":"VBox"}],"answer":"A","answerText":"FlowPane","explanation":"Pane (and its base layouts without layout algorithms) positions child nodes at absolute coordinates (relocate/setLayoutX/setLayoutY) without automatic alignment or flow management."},{"id":18,"partId":2,"partTitle":"Part 2: Layout Management & Container Hierarchy","prompt":"In JavaFX layout management, what does setting a node's preferred width to USE_COMPUTED_SIZE instruct the layout manager to do?","code":null,"choices":[{"letter":"A","text":"Force the node to expand to fill the entire desktop monitor screen."},{"letter":"B","text":"Automatically compute the node's dimensions based on its child elements and content."},{"letter":"C","text":"Restrict the node to a fixed zero-pixel dimension."},{"letter":"D","text":"Defer sizing calculations to operating system desktop themes."}],"answer":"B","answerText":"Automatically compute the node's dimensions based on its child elements and content.","explanation":"Setting a size to Region.USE_COMPUTED_SIZE directs the layout manager to automatically calculate optimal dimensions based on node content and child constraints."},{"id":19,"partId":2,"partTitle":"Part 2: Layout Management & Container Hierarchy","prompt":"How does the VBox layout container arrange its child nodes in the scene graph?","code":null,"choices":[{"letter":"A","text":"Sequentially in a single horizontal row from left to right."},{"letter":"B","text":"Centered on top of each other along the z-axis."},{"letter":"C","text":"Sequentially in a single vertical column from top to bottom."},{"letter":"D","text":"In a flexible two-dimensional grid of rows and columns."}],"answer":"C","answerText":"Sequentially in a single vertical column from top to bottom.","explanation":"VBox (Vertical Box) positions its child nodes sequentially in a single vertical column from top to bottom."},{"id":20,"partId":2,"partTitle":"Part 2: Layout Management & Container Hierarchy","prompt":"Which property of a VBox allows developers to define uniform vertical empty space between adjacent child nodes?","code":null,"choices":[{"letter":"A","text":"hgap"},{"letter":"B","text":"spacing"},{"letter":"C","text":"rowSpan"},{"letter":"D","text":"dividerPosition"}],"answer":"B","answerText":"spacing","explanation":"The spacing property of VBox defines the vertical distance (in pixels) between consecutive child nodes within the container."},{"id":21,"partId":2,"partTitle":"Part 2: Layout Management & Container Hierarchy","prompt":"Into how many distinct regions does a BorderPane layout container organize child nodes?","code":null,"choices":[{"letter":"A","text":"Three (Top, Middle, Bottom)"},{"letter":"B","text":"Four (North, South, East, West)"},{"letter":"C","text":"Five (Top, Bottom, Left, Center, Right)"},{"letter":"D","text":"Nine fixed cells in a 3x3 matrix"}],"answer":"C","answerText":"Five (Top, Bottom, Left, Center, Right)","explanation":"BorderPane organizes its children into five spatial regions: Top, Bottom, Left, Right, and Center."},{"id":22,"partId":2,"partTitle":"Part 2: Layout Management & Container Hierarchy","prompt":"In a BorderPane, if both the Left and Right areas are left empty, how does the Center region respond?","code":null,"choices":[{"letter":"A","text":"The Center area collapses to zero width."},{"letter":"B","text":"The Center area expands horizontally to occupy the available empty side space."},{"letter":"C","text":"The BorderPane throws an IllegalStateException at runtime."},{"letter":"D","text":"The Top and Bottom areas shrink inward to match the Center width."}],"answer":"B","answerText":"The Center area expands horizontally to occupy the available empty side space.","explanation":"In BorderPane, the Center region expands dynamically to fill all available space not occupied by Top, Bottom, Left, or Right regions. If Left and Right are absent, Center fills the full middle width."},{"id":23,"partId":2,"partTitle":"Part 2: Layout Management & Container Hierarchy","prompt":"What is the spatial behavior of the Top and Bottom regions of a BorderPane?","code":null,"choices":[{"letter":"A","text":"They occupy the full width of the BorderPane and are vertically sized to their children's preferred heights."},{"letter":"B","text":"They are fixed at a constant 100-pixel height regardless of content."},{"letter":"C","text":"They share horizontal space equally with the Left and Right regions."},{"letter":"D","text":"They automatically float in the center of the viewport."}],"answer":"A","answerText":"They occupy the full width of the BorderPane and are vertically sized to their children's preferred heights.","explanation":"In BorderPane, the Top and Bottom regions span horizontally across the entire width of the container, extending across the left, center, and right sections."},{"id":24,"partId":2,"partTitle":"Part 2: Layout Management & Container Hierarchy","prompt":"Which layout container arranges nodes in a flexible rectangular grid composed of rows and columns?","code":null,"choices":[{"letter":"A","text":"FlowPane"},{"letter":"B","text":"AnchorPane"},{"letter":"C","text":"GridPane"},{"letter":"D","text":"StackPane"}],"answer":"C","answerText":"GridPane","explanation":"GridPane lays out its children in a flexible two-dimensional grid composed of rows and columns, where each cell is addressed by column and row indices."},{"id":25,"partId":2,"partTitle":"Part 2: Layout Management & Container Hierarchy","prompt":"In a GridPane, what is the key difference between padding and the gap properties (hgap / vgap)?","code":null,"choices":[{"letter":"A","text":"padding separates child nodes from each other, whereas hgap/vgap separate the container from the window edge."},{"letter":"B","text":"padding insets the content from the container's outer edges, whereas hgap/vgap define spacing between cells."},{"letter":"C","text":"padding applies only to text controls, while gaps apply only to images."},{"letter":"D","text":"There is no functional difference; they are aliases for the same layout property."}],"answer":"B","answerText":"padding insets the content from the container's outer edges, whereas hgap/vgap define spacing between cells.","explanation":"Padding sets empty space along the outer perimeter boundary of the container, whereas hgap and vgap specify spacing between adjacent rows and columns inside the grid."},{"id":26,"partId":2,"partTitle":"Part 2: Layout Management & Container Hierarchy","prompt":"Which layout pane displays a collapsible panel with a title bar that expands or collapses its contents when clicked?","code":null,"choices":[{"letter":"A","text":"Accordion"},{"letter":"B","text":"TitledPane"},{"letter":"C","text":"TabPane"},{"letter":"D","text":"SplitPane"}],"answer":"B","answerText":"TitledPane","explanation":"TitledPane is a control with a title bar that can be clicked by the user to expand or collapse the content panel underneath it."},{"id":27,"partId":2,"partTitle":"Part 2: Layout Management & Container Hierarchy","prompt":"What is the layout behavior of a horizontal FlowPane when child nodes exceed the pane's width?","code":null,"choices":[{"letter":"A","text":"It clips and hides nodes that exceed the boundary."},{"letter":"B","text":"It automatically wraps excess nodes onto a new row."},{"letter":"C","text":"It dynamically scales down the size of all children to fit on one row."},{"letter":"D","text":"It throws an IndexOutOfBoundsException during layout recalculation."}],"answer":"B","answerText":"It automatically wraps excess nodes onto a new row.","explanation":"A horizontal FlowPane lays out its children sequentially in a row; when the available horizontal space is exhausted, subsequent children wrap automatically to the next row."},{"id":28,"partId":2,"partTitle":"Part 2: Layout Management & Container Hierarchy","prompt":"Which layout container arranges nodes in a back-to-front stack where each new node is rendered atop the previous one?","code":null,"choices":[{"letter":"A","text":"TilePane"},{"letter":"B","text":"StackPane"},{"letter":"C","text":"ButtonBar"},{"letter":"D","text":"TextFlow"}],"answer":"B","answerText":"StackPane","explanation":"StackPane places child nodes on top of each other in a back-to-front stack (z-order), where nodes added later render over earlier nodes."},{"id":29,"partId":2,"partTitle":"Part 2: Layout Management & Container Hierarchy","prompt":"If a developer needs to divide a GUI layout into user-resizable view areas separated by draggable splitters, which container is required?","code":null,"choices":[{"letter":"A","text":"ScrollPane"},{"letter":"B","text":"SplitPane"},{"letter":"C","text":"DialogPane"},{"letter":"D","text":"AnchorPane"}],"answer":"B","answerText":"SplitPane","explanation":"SplitPane divides its container space into multiple panels separated by draggable dividers that users can reposition interactively at runtime."},{"id":30,"partId":2,"partTitle":"Part 2: Layout Management & Container Hierarchy","prompt":"How can a control in a GridPane be configured to occupy multiple rows or columns simultaneously?","code":null,"choices":[{"letter":"A","text":"By applying the padding and spacing attributes."},{"letter":"B","text":"By configuring the Row Span or Column Span properties."},{"letter":"C","text":"By nesting the control inside a TitledPane."},{"letter":"D","text":"By setting its focusTraversable property to true."}],"answer":"B","answerText":"By configuring the Row Span or Column Span properties.","explanation":"GridPane provides static convenience methods GridPane.setColumnSpan(Node, int) and GridPane.setRowSpan(Node, int) to make a control span multiple cells."},{"id":31,"partId":3,"partTitle":"Part 3: Event-Driven Programming & Interactive Controls","prompt":"What defines an event-driven desktop application architecture?","code":null,"choices":[{"letter":"A","text":"The application executes instructions strictly in a linear order from the first line of main to the last."},{"letter":"B","text":"User interactions (e.g., clicking buttons, moving sliders, dragging mice) generate events that trigger handler methods."},{"letter":"C","text":"The application polls the CPU clock every millisecond to recalculate layout geometry."},{"letter":"D","text":"The application logic is governed entirely by backend database triggers rather than UI inputs."}],"answer":"B","answerText":"User interactions (e.g., clicking buttons, moving sliders, dragging mice) generate events that trigger handler methods.","explanation":"An event-driven architecture is asynchronous and reactive: the program enters an event loop waiting for external events (clicks, keypresses, timers) and dispatches handlers when events occur."},{"id":32,"partId":3,"partTitle":"Part 3: Event-Driven Programming & Interactive Controls","prompt":"Which class in package javafx.event represents high-level user actions, such as clicking a Button or choosing a menu item?","code":null,"choices":[{"letter":"A","text":"InputEvent"},{"letter":"B","text":"ActionEvent"},{"letter":"C","text":"MotionEvent"},{"letter":"D","text":"TriggerEvent"}],"answer":"B","answerText":"ActionEvent","explanation":"ActionEvent represents high-level user semantic actions on controls, such as pushing a Button, selecting a MenuItem, or pressing Enter in a TextField."},{"id":33,"partId":3,"partTitle":"Part 3: Event-Driven Programming & Interactive Controls","prompt":"What is the required signature for an event-handling method declared in a JavaFX controller to handle a Button click?","code":null,"choices":[{"letter":"A","text":"public boolean onAction(Event e)"},{"letter":"B","text":"@FXML private void methodName(ActionEvent event)"},{"letter":"C","text":"@FXML public int handleAction(Object source)"},{"letter":"D","text":"private ActionEvent processClick()"}],"answer":"B","answerText":"@FXML private void methodName(ActionEvent event)","explanation":"An FXML event-handler method in a controller requires @FXML private void methodName(ActionEvent event) (or parameterless) so the FXMLLoader can bind the onAction attribute."},{"id":34,"partId":3,"partTitle":"Part 3: Event-Driven Programming & Interactive Controls","prompt":"To ensure that only one RadioButton within a group can be selected at a time, the controls must be associated with an instance of:","code":null,"choices":[{"letter":"A","text":"ButtonGroup"},{"letter":"B","text":"ToggleGroup"},{"letter":"C","text":"RadioManager"},{"letter":"D","text":"SelectionGroup"}],"answer":"B","answerText":"ToggleGroup","explanation":"RadioButton controls must be grouped using a ToggleGroup instance so that selecting one radio button automatically deselects all other radio buttons in the group."},{"id":35,"partId":3,"partTitle":"Part 3: Event-Driven Programming & Interactive Controls","prompt":"How can arbitrary custom objects (such as a domain model, Color, or enum constant) be directly attached to a JavaFX control?","code":null,"choices":[{"letter":"A","text":"By storing them in the control’s setAccessibleHelp() field."},{"letter":"B","text":"By calling the control’s setUserData(Object value) method."},{"letter":"C","text":"By setting the control’s fx:id to the serialized object string."},{"letter":"D","text":"By modifying the CSS style attribute directly."}],"answer":"B","answerText":"By calling the control’s setUserData(Object value) method.","explanation":"The Node.setUserData(Object) and getUserData() methods allow developers to attach arbitrary user objects, metadata, or models directly to any scene graph node."},{"id":36,"partId":3,"partTitle":"Part 3: Event-Driven Programming & Interactive Controls","prompt":"Which mouse event occurs continuously when the user presses a mouse button over a node and moves the cursor while holding the button down?","code":null,"choices":[{"letter":"A","text":"onMouseClicked"},{"letter":"B","text":"onMouseMoved"},{"letter":"C","text":"onMouseDragged"},{"letter":"D","text":"onMouseEntered"}],"answer":"C","answerText":"onMouseDragged","explanation":"MouseEvent.MOUSE_DRAGGED is delivered continuously when the user presses and holds a mouse button over a node while moving the pointer."},{"id":37,"partId":3,"partTitle":"Part 3: Event-Driven Programming & Interactive Controls","prompt":"Inside a MouseEvent handler, how do you determine the horizontal and vertical coordinates of the interaction relative to the target node?","code":null,"choices":[{"letter":"A","text":"By querying e.getScenePosition() and e.getScreenPosition()."},{"letter":"B","text":"By calling e.getX() and e.getY()."},{"letter":"C","text":"By reading e.getTop() and e.getLeft()."},{"letter":"D","text":"By parsing e.getCoordinatesAsString()."}],"answer":"B","answerText":"By calling e.getX() and e.getY().","explanation":"In MouseEvent handlers, getX() and getY() return cursor coordinates relative to the event source/target node, whereas getScreenX() and getScreenY() return absolute screen coordinates."},{"id":38,"partId":3,"partTitle":"Part 3: Event-Driven Programming & Interactive Controls","prompt":"In a drawing canvas implementation using a Pane, how is a newly created Circle node dynamically rendered on screen?","code":null,"choices":[{"letter":"A","text":"drawingAreaPane.setNode(newCircle);"},{"letter":"B","text":"drawingAreaPane.getChildren().add(newCircle);"},{"letter":"C","text":"Scene.getRoot().attach(newCircle);"},{"letter":"D","text":"FXMLLoader.inject(drawingAreaPane, newCircle);"}],"answer":"B","answerText":"drawingAreaPane.getChildren().add(newCircle);","explanation":"A Pane stores its child visual elements in an ObservableList accessed via getChildren(); adding a Circle node via pane.getChildren().add(circle) attaches it to the scene graph for rendering."},{"id":39,"partId":3,"partTitle":"Part 3: Event-Driven Programming & Interactive Controls","prompt":"What return type is produced by a layout pane's getChildren() method?","code":null,"choices":[{"letter":"A","text":"java.util.Vector"},{"letter":"B","text":"javafx.collections.ObservableList"},{"letter":"C","text":"java.util.HashSet"},{"letter":"D","text":"javafx.beans.property.ListProperty"}],"answer":"B","answerText":"javafx.collections.ObservableList","explanation":"The getChildren() method of Parent/Pane returns an ObservableList<Node>, which automatically notifies the scene graph whenever nodes are added, removed, or rearranged."},{"id":40,"partId":3,"partTitle":"Part 3: Event-Driven Programming & Interactive Controls","prompt":"How does a JavaFX controller implement an Undo feature that removes the most recently drawn shape from a Pane?","code":null,"choices":[{"letter":"A","text":"pane.getChildren().clear();"},{"letter":"B","text":"pane.getChildren().remove(pane.getChildren().size() - 1);"},{"letter":"C","text":"pane.setClip(null);"},{"letter":"D","text":"pane.getChildren().removeAll();"}],"answer":"B","answerText":"pane.getChildren().remove(pane.getChildren().size() - 1);","explanation":"To undo the last drawn element, removing the final child node from the pane's children list via getChildren().remove(getChildren().size() - 1) detaches it from the scene graph."},{"id":41,"partId":4,"partTitle":"Part 4: Properties, ChangeListeners, Binding & MVC","prompt":"Why can changes to a Slider control's numeric value property NOT be registered as simple @FXML action handlers in Scene Builder?","code":null,"choices":[{"letter":"A","text":"Sliders do not support user interaction."},{"letter":"B","text":"Sliders fire property-change events on observable values rather than basic action events, requiring a ChangeListener registered in code."},{"letter":"C","text":"Sliders can only be modified through external CSS style sheets."},{"letter":"D","text":"Scene Builder does not recognize numeric sliders as GUI components."}],"answer":"B","answerText":"Sliders fire property-change events on observable values rather than basic action events, requiring a ChangeListener registered in code.","explanation":"Slider value changes are continuous property state mutations tracked through valueProperty() rather than discrete semantic button-press actions represented by onAction."},{"id":42,"partId":4,"partTitle":"Part 4: Properties, ChangeListeners, Binding & MVC","prompt":"Which functional interface from package javafx.beans.value is implemented to observe and respond to changes in a JavaFX property?","code":null,"choices":[{"letter":"A","text":"javafx.event.EventHandler"},{"letter":"B","text":"javafx.beans.value.ChangeListener"},{"letter":"C","text":"java.awt.event.ActionListener"},{"letter":"D","text":"java.util.Observer"}],"answer":"B","answerText":"javafx.beans.value.ChangeListener","explanation":"javafx.beans.value.ChangeListener<T> is the functional interface implemented to monitor and handle changes in any JavaFX ObservableValue or property."},{"id":43,"partId":4,"partTitle":"Part 4: Properties, ChangeListeners, Binding & MVC","prompt":"What three parameters are passed to the changed method of the ChangeListener interface?","code":null,"choices":[{"letter":"A","text":"(Event e, Node source, Node target)"},{"letter":"B","text":"(ObservableValue ov, T oldValue, T newValue)"},{"letter":"C","text":"(int index, String key, Object data)"},{"letter":"D","text":"(Stage stage, Scene scene, Parent root)"}],"answer":"B","answerText":"(ObservableValue ov, T oldValue, T newValue)","explanation":"The changed(ObservableValue<? extends T> observable, T oldValue, T newValue) method receives the property being observed, the previous value before the change, and the updated new value."},{"id":44,"partId":4,"partTitle":"Part 4: Properties, ChangeListeners, Binding & MVC","prompt":"Consider the code snippet below. What feature of modern Java is being used to implement the ChangeListener?","code":"slider.valueProperty().addListener((ov, oldValue, newValue) -> {\n    label.setText(String.format(\"%.0f\", newValue.doubleValue()));\n});","choices":[{"letter":"A","text":"An anonymous inner class implementing Runnable."},{"letter":"B","text":"A lambda expression implementing a single-abstract-method (SAM) functional interface."},{"letter":"C","text":"A static method reference to an unmanaged thread."},{"letter":"D","text":"Reflection metadata invocation."}],"answer":"B","answerText":"A lambda expression implementing a single-abstract-method (SAM) functional interface.","explanation":"The arrow syntax (ov, oldValue, newValue) -> { ... } is a Java lambda expression implementing the single-abstract-method (SAM) ChangeListener interface."},{"id":45,"partId":4,"partTitle":"Part 4: Properties, ChangeListeners, Binding & MVC","prompt":"In defensive UI programming, what do the methods requestFocus() and selectAll() accomplish on a TextField during input validation failure?","code":null,"choices":[{"letter":"A","text":"They disable the text field and hide the stage."},{"letter":"B","text":"They direct user focus back to the text field and highlight the invalid text for rapid re-entry."},{"letter":"C","text":"They clear the text field and delete the controller instance."},{"letter":"D","text":"They immediately terminate the Java Virtual Machine."}],"answer":"B","answerText":"They direct user focus back to the text field and highlight the invalid text for rapid re-entry.","explanation":"Calling requestFocus() places the keyboard cursor into the invalid TextField, while selectAll() highlights all invalid input text so the user can immediately overwrite it."},{"id":46,"partId":4,"partTitle":"Part 4: Properties, ChangeListeners, Binding & MVC","prompt":"In the Model-View-Controller (MVC) architectural pattern as applied to JavaFX FXML applications, what is the role of the View?","code":null,"choices":[{"letter":"A","text":"It encapsulates business calculations and database entities."},{"letter":"B","text":"It defines the visual layout and controls presented on the screen, typically declared in FXML."},{"letter":"C","text":"It acts as the event dispatcher routing requests to backend services."},{"letter":"D","text":"It stores static database connection pools."}],"answer":"B","answerText":"It defines the visual layout and controls presented on the screen, typically declared in FXML.","explanation":"In MVC, the View is strictly responsible for presentation and layout (declared in FXML), displaying data to the user without containing core calculation or data-persistence logic."},{"id":47,"partId":4,"partTitle":"Part 4: Properties, ChangeListeners, Binding & MVC","prompt":"In the MVC pattern, which component processes user inputs, updates the model, and synchronizes the view?","code":null,"choices":[{"letter":"A","text":"The Scene Graph Root"},{"letter":"B","text":"The Controller"},{"letter":"C","text":"The Stage Window"},{"letter":"D","text":"The CSS Stylesheet"}],"answer":"B","answerText":"The Controller","explanation":"The Controller serves as the mediator in MVC: it receives user input events from the View, mutates the underlying Model, and updates the View to reflect data changes."},{"id":48,"partId":4,"partTitle":"Part 4: Properties, ChangeListeners, Binding & MVC","prompt":"What naming convention defines a read/write JavaFX property named amount of type DoubleProperty in a custom domain class?","code":null,"choices":[{"letter":"A","text":"setAmount(double v), getAmount(), and amountProperty()"},{"letter":"B","text":"writeAmount(double v), readAmount(), and listenAmount()"},{"letter":"C","text":"mutateAmount(double v), accessAmount(), and bindAmount()"},{"letter":"D","text":"storeAmount(double v), fetchAmount(), and propertyOfAmount()"}],"answer":"A","answerText":"setAmount(double v), getAmount(), and amountProperty()","explanation":"The JavaFX property bean convention requires three methods for a property named amount: getter getAmount(), setter setAmount(double), and property accessor amountProperty()."},{"id":49,"partId":4,"partTitle":"Part 4: Properties, ChangeListeners, Binding & MVC","prompt":"Why should getter and setter methods that manipulate JavaFX properties typically be declared final?","code":null,"choices":[{"letter":"A","text":"To prevent compiler warnings about unused variables."},{"letter":"B","text":"To prevent subclasses from overriding them, which could lead to unexpected behavior in client property bindings."},{"letter":"C","text":"To force the JVM to allocate them in read-only permanent memory."},{"letter":"D","text":"To convert primitive numeric types into Java records automatically."}],"answer":"B","answerText":"To prevent subclasses from overriding them, which could lead to unexpected behavior in client property bindings.","explanation":"Declaring property getter and setter methods final prevents subclasses from overriding them with divergent logic, safeguarding property binding consistency and enabling compiler inlining."},{"id":50,"partId":4,"partTitle":"Part 4: Properties, ChangeListeners, Binding & MVC","prompt":"What occurs when a unidirectional property binding is established between a TextField's textProperty and a Slider's valueProperty?","code":null,"choices":[{"letter":"A","text":"The slider moves whenever the user types numbers into the text field."},{"letter":"B","text":"The text field updates automatically when the slider moves, and direct user editing in the text field is disabled."},{"letter":"C","text":"Both controls are removed from the Scene Graph."},{"letter":"D","text":"A cyclic loop triggers a StackOverflowError."}],"answer":"B","answerText":"The text field updates automatically when the slider moves, and direct user editing in the text field is disabled.","explanation":"A unidirectional binding (e.g. textProperty().bind(slider.valueProperty())) synchronizes the target with the source while making the target property unmodifiable directly."},{"id":51,"partId":4,"partTitle":"Part 4: Properties, ChangeListeners, Binding & MVC","prompt":"Which method converts a numeric DoubleProperty into an ObservableValue using format-control strings for property binding?","code":null,"choices":[{"letter":"A","text":"asFormat(String format)"},{"letter":"B","text":"asString(String format)"},{"letter":"C","text":"formatToString(String pattern)"},{"letter":"D","text":"toObservableText(String mask)"}],"answer":"B","answerText":"asString(String format)","explanation":"The asString(String format) method of DoubleProperty converts the numeric property into an ObservableStringValue formatted according to standard Java format specifiers (e.g. \"%.2f\")."},{"id":52,"partId":4,"partTitle":"Part 4: Properties, ChangeListeners, Binding & MVC","prompt":"Which GoF (Gang of Four) software design pattern is directly implemented by JavaFX's ObservableList and property listener mechanism?","code":null,"choices":[{"letter":"A","text":"Singleton Pattern"},{"letter":"B","text":"Factory Method Pattern"},{"letter":"C","text":"Observer Pattern"},{"letter":"D","text":"Adapter Pattern"}],"answer":"C","answerText":"Observer Pattern","explanation":"The Observer Pattern is implemented by ObservableList and ObservableValue: subjects maintain a list of dependent observers/listeners and notify them automatically upon state change."},{"id":53,"partId":5,"partTitle":"Part 5: Advanced Controls, Collections, ListCell Rendering & Dialogs","prompt":"How is an empty observable list created using the JavaFX collections utility class?","code":null,"choices":[{"letter":"A","text":"ObservableList list = new ObservableList();"},{"letter":"B","text":"ObservableList list = FXCollections.observableArrayList();"},{"letter":"C","text":"ObservableList list = Collections.synchronizedList();"},{"letter":"D","text":"ObservableList list = new ArrayList<Observable>();"}],"answer":"B","answerText":"ObservableList list = FXCollections.observableArrayList();","explanation":"FXCollections.observableArrayList() is the standard factory method in JavaFX to instantiate an empty, observable ArrayList backed by collection change notifications."},{"id":54,"partId":5,"partTitle":"Part 5: Advanced Controls, Collections, ListCell Rendering & Dialogs","prompt":"When an ObservableList is bound to a ListView via setItems(), what visual behavior occurs when items are added to or removed from the list?","code":null,"choices":[{"letter":"A","text":"The ListView throws an UnsupportedOperationException unless refreshed manually."},{"letter":"B","text":"The ListView automatically updates its visual presentation in response to collection mutations."},{"letter":"C","text":"The underlying Stage reloads the entire FXML file from disk."},{"letter":"D","text":"The ListView caches the initial list items permanently and ignores all mutations."}],"answer":"B","answerText":"The ListView automatically updates its visual presentation in response to collection mutations.","explanation":"Binding an ObservableList to a ListView causes the control to listen for collection change events and automatically re-render rows when elements are added, deleted, or updated."},{"id":55,"partId":5,"partTitle":"Part 5: Advanced Controls, Collections, ListCell Rendering & Dialogs","prompt":"How do you register an event listener that executes when the user selects a different item inside a ListView?","code":null,"choices":[{"letter":"A","text":"listView.addActionListener(e -> ...);"},{"letter":"B","text":"listView.setOnItemClick(item -> ...);"},{"letter":"C","text":"listView.getSelectionModel().selectedItemProperty().addListener(...);"},{"letter":"D","text":"listView.getProperties().addPropertyChangeListener(...);"}],"answer":"C","answerText":"listView.getSelectionModel().selectedItemProperty().addListener(...);","explanation":"To detect selection changes on a ListView, attach a ChangeListener to listView.getSelectionModel().selectedItemProperty() or selectedIndexProperty()."},{"id":56,"partId":5,"partTitle":"Part 5: Advanced Controls, Collections, ListCell Rendering & Dialogs","prompt":"To customize the presentation of items in a ListView beyond their default toString() representation, a developer must create a subclass of:","code":null,"choices":[{"letter":"A","text":"javafx.scene.control.TableCell"},{"letter":"B","text":"javafx.scene.control.ListCell"},{"letter":"C","text":"javafx.scene.layout.CellPane"},{"letter":"D","text":"javafx.scene.control.ItemRenderer"}],"answer":"B","answerText":"javafx.scene.control.ListCell","explanation":"javafx.scene.control.ListCell<T> is the visual component class subclassed to customize row rendering, formatting, and layout inside a ListView."},{"id":57,"partId":5,"partTitle":"Part 5: Advanced Controls, Collections, ListCell Rendering & Dialogs","prompt":"Which method MUST be overridden in a custom ListCell subclass to configure cell graphics and text?","code":null,"choices":[{"letter":"A","text":"public void renderNode(T item)"},{"letter":"B","text":"protected void updateItem(T item, boolean empty)"},{"letter":"C","text":"public void setGraphicContent(T item)"},{"letter":"D","text":"protected void drawCell(T item, int index)"}],"answer":"B","answerText":"protected void updateItem(T item, boolean empty)","explanation":"Custom ListCell implementations must override protected void updateItem(T item, boolean empty) to configure cell text, graphics, and styles based on the item and empty status."},{"id":58,"partId":5,"partTitle":"Part 5: Advanced Controls, Collections, ListCell Rendering & Dialogs","prompt":"In a custom ListCell implementation, what critical instruction must be executed if empty == true or item == null?","code":null,"choices":[{"letter":"A","text":"throw new NullPointerException();"},{"letter":"B","text":"setGraphic(null);"},{"letter":"C","text":"getChildren().clear();"},{"letter":"D","text":"System.exit(0);"}],"answer":"B","answerText":"setGraphic(null);","explanation":"Because ListView reuses and virtualizes cell instances, when empty == true or item == null, the cell must clear its display by calling setText(null) and setGraphic(null) to prevent ghost data."},{"id":59,"partId":5,"partTitle":"Part 5: Advanced Controls, Collections, ListCell Rendering & Dialogs","prompt":"What is considered best practice for optimizing performance and minimizing memory allocation when writing a custom ListCell?","code":null,"choices":[{"letter":"A","text":"Reinstantiating all layout containers and image views inside updateItem on every call."},{"letter":"B","text":"Instantiating the container and child controls once in the ListCell constructor as instance variables, and only updating contents in updateItem."},{"letter":"C","text":"Creating a new Stage and Scene for every row in the list."},{"letter":"D","text":"Avoiding the use of ObservableList entirely."}],"answer":"B","answerText":"Instantiating the container and child controls once in the ListCell constructor as instance variables, and only updating contents in updateItem.","explanation":"To maximize scrolling performance and minimize GC pauses, cell layout containers and nodes should be instantiated once in the ListCell constructor and only populated in updateItem."},{"id":60,"partId":5,"partTitle":"Part 5: Advanced Controls, Collections, ListCell Rendering & Dialogs","prompt":"How does displaying a FileChooser as a modal dialog using showOpenDialog(window) influence user interaction with the application?","code":null,"choices":[{"letter":"A","text":"It minimizes the application window to the operating system taskbar."},{"letter":"B","text":"It opens an asynchronous non-blocking thread allowing concurrent editing in background windows."},{"letter":"C","text":"It blocks the user from interacting with the underlying application window until the dialog is closed or dismissed."},{"letter":"D","text":"It forces the Java Virtual Machine to terminate background task worker threads."}],"answer":"C","answerText":"It blocks the user from interacting with the underlying application window until the dialog is closed or dismissed.","explanation":"Calling FileChooser.showOpenDialog(window) displays a modal file picker that captures interaction and blocks user input to parent windows until dismissed."}]},"java-oop-150":{"id":"java-oop-150","title":"Java Object-Oriented Programming (OOP) Active Recall Questionnaire","desc":"Comprehensive 150-question active recall questionnaire covering core Java OOP principles, inheritance, polymorphism, constructor chaining, operator precedence, string and StringBuilder manipulation, collections, loops, and exception handling.","parts":[{"id":1,"title":"Part 1: Inheritance, Abstract Classes & Overloading","desc":"Abstract classes, Beetle exoskeleton hierarchy, TurtleFrog references, and method overloading rules. (Questions 1–10)","range":[1,10]},{"id":2,"title":"Part 2: Abstract Classes vs. Interfaces Foundations","desc":"Contracts, instantiation rules, extends vs implements keywords, and concrete subclass duties. (Questions 11–20)","range":[11,20]},{"id":3,"title":"Part 3: Interface Inheritance & Default Methods","desc":"Interface extension chains, default method resolution, Owl isBlind() dispatch, and overloading. (Questions 21–30)","range":[21,30]},{"id":4,"title":"Part 4: Interface Modifiers, Final Methods & Object State","desc":"Implicit public/static/final modifiers, Reptile layEggs() final constraint, and Orca polymorphism. (Questions 31–40)","range":[31,40]},{"id":5,"title":"Part 5: Class Extension, Constructors & Overloading","desc":"Platypus super() constructor chaining, superclass constructor rules, and ClownFish gill overloading. (Questions 41–50)","range":[41,50]},{"id":6,"title":"Part 6: Interface Access Rules, Visibility & Polymorphism","desc":"Implicit interface modifiers, default returns, Owl casting semantics, and access privilege weakening. (Questions 51–60)","range":[51,60]},{"id":7,"title":"Part 7: Variable Scopes, Imports & Loop Execution","desc":"Block vs class variables, java.lang defaults, loop counts, break/continue flow, and declaration scope. (Questions 61–70)","range":[61,70]},{"id":8,"title":"Part 8: Operators, Precedence, Control Flow & Arrays","desc":"Static fields, pre-increment ++y, integer division, array indexing, and string literal concatenation. (Questions 71–80)","range":[71,80]},{"id":9,"title":"Part 9: Advanced Evaluation Order, Switch & Overloading","desc":"Prefix increment promotion, switch statement cases, valid method identifiers, and varargs rules. (Questions 81–90)","range":[81,90]},{"id":10,"title":"Part 10: Variable Scopes (Block, Method, Instance, Class & Interface)","desc":"Scope lifetimes, pass-by-value semantics, method-local vs instance variables, and constant access. (Questions 91–100)","range":[91,100]},{"id":11,"title":"Part 11: StringBuilder, String Immutability & Package Imports","desc":"StringBuilder character indexing, String equality vs references, wildcard imports, and java.lang defaults. (Questions 101–110)","range":[101,110]},{"id":12,"title":"Part 12: String Methods (substring, concat, indexOf) & Array Bounds","desc":"Immutability of concat(), substring slicing, indexOf delimiter parsing, and array length properties. (Questions 111–120)","range":[111,120]},{"id":13,"title":"Part 13: Array Traversal, ArrayList Operations & Loop Semantics","desc":"ArrayList size() vs capacity, for-each traversal order, backward array indexing, and zero-based indexing. (Questions 121–130)","range":[121,130]},{"id":14,"title":"Part 14: Checked vs Unchecked Exceptions & try-catch Structure","desc":"Checked exception declaration requirements, runtime exceptions, array out of bounds, and catch block ordering. (Questions 131–140)","range":[131,140]},{"id":15,"title":"Part 15: Exception Hierarchy, Arithmetic Errors, finally Blocks & Type Promotion","desc":"ArithmeticException divide by zero, unreachable IOException catch rules, finally execution, and byte arithmetic promotion. (Questions 141–150)","range":[141,150]}],"questions":[{"id":1,"partId":1,"partTitle":"Part 1: Inheritance, Abstract Classes & Overloading","prompt":"Consider the following Java code:\nWhat is the result when this code is compiled?","code":"interface HasExoskeleton {\nabstract int getNumberOfSections();\n}\nabstract class Insect implements HasExoskeleton {\nabstract int getNumberOfLegs():\n}\npublic class Beetle extends Insect  {\nint getNumberOfLegs()  {\nreturn 6;\n}\n}","choices":[{"letter":"A","text":"** It compiles and runs without an issue."},{"letter":"B","text":"** There is a compile error at line 02."},{"letter":"C","text":"** There is a compile error at line 04."},{"letter":"D","text":"** There is a compile error at line 07."},{"letter":"E","text":"** It compiles but throws an exception."}],"answer":"D","answerText":"There is a compile error at line 07.","explanation":"Beetle is a concrete class and does not implement getNumberOfSections() inherited from HasExoskeleton."},{"id":2,"partId":1,"partTitle":"Part 1: Inheritance, Abstract Classes & Overloading","prompt":"In Java, an abstract class implements an interface but does not provide an implementation for every inherited abstract method. What may the abstract class do?","code":null,"choices":[{"letter":"A","text":"** Remain abstract and defer the implementation."},{"letter":"B","text":"** Become final and defer the implementation."},{"letter":"C","text":"** Change the interface into a concrete class."},{"letter":"D","text":"** Override only methods with return values."},{"letter":"E","text":"** Declare every inherited method private."}],"answer":"A","answerText":"Remain abstract and defer the implementation.","explanation":"An abstract class is permitted to defer the implementation of interface methods to its subclasses."},{"id":3,"partId":1,"partTitle":"Part 1: Inheritance, Abstract Classes & Overloading","prompt":"In the code involving HasExoskeleton, Insect, and Beetle, which method must Beetle implement before it can be a concrete class?","code":null,"choices":[{"letter":"A","text":"** getNumberOfLegs() only"},{"letter":"B","text":"** getNumberOfSections() only"},{"letter":"C","text":"** Both inherited methods"},{"letter":"D","text":"** Neither inherited method"},{"letter":"E","text":"** The interface constructor"}],"answer":"C","answerText":"Both inherited methods (or B: getNumberOfSections() only)","explanation":"A concrete class must implement all inherited abstract methods; in this specific code, getNumberOfSections() is the missing implementation."},{"id":4,"partId":1,"partTitle":"Part 1: Inheritance, Abstract Classes & Overloading","prompt":"Consider these Java declarations:\nWhich declaration can replace the blank and allow the code to compile?","code":"public interface CanHop {}\npublic class Frog implements CanHop  {\n}\npublic class HornedFrog extends Frog  {\n}\npublic class TurtleFrog extends Frog  {\n}\npublic class Test  {\npublic static void main(String[] args) {\n____ frog = new TurtleFrog():\n}\n}","choices":[{"letter":"A","text":"** Frog"},{"letter":"B","text":"** HornedFrog"},{"letter":"C","text":"** String"},{"letter":"D","text":"** Long"}],"answer":"A","answerText":"Frog","explanation":"TurtleFrog extends Frog, so Frog is a valid superclass reference type."},{"id":5,"partId":1,"partTitle":"Part 1: Inheritance, Abstract Classes & Overloading","prompt":"Using the declarations Frog implements CanHop and TurtleFrog extends Frog which relationship makes a variable of type CanHop able to reference a TurtleFrog object?","code":null,"choices":[{"letter":"A","text":"** TurtleFrog inherits the CanHop type through Frog."},{"letter":"B","text":"** CanHop inherits all classes from TurtleFrog."},{"letter":"C","text":"** Frog objects cannot implement interfaces."},{"letter":"D","text":"** TurtleFrog must extend CanHop directly."}],"answer":"A","answerText":"TurtleFrog inherits the CanHop type through Frog.","explanation":"A subclass inherits all interface implementations from its superclasses."},{"id":6,"partId":1,"partTitle":"Part 1: Inheritance, Abstract Classes & Overloading","prompt":"For the statement Frog frog = new TurtleFrog(). what is the declared type of the variable frog?","code":null,"choices":[{"letter":"A","text":"** The superclass type Frog"},{"letter":"B","text":"** The subclass type TurtleFrog"},{"letter":"C","text":"** The interface type CanHop"},{"letter":"D","text":"** The reference type Object"}],"answer":"A","answerText":"The superclass type Frog","explanation":"The declared type (reference type) of variable frog is Frog."},{"id":7,"partId":1,"partTitle":"Part 1: Inheritance, Abstract Classes & Overloading","prompt":"// method body continues Does printName(int) override printName(double)?","code":"class Arthropod {\npublic void printName(double input) {\nSystem.out.print(\"Arthropod\"):\n}\n}\npublic class Spider extends Arthropod  {\npublic void printName(int input)  {\n}\n}","choices":[{"letter":"A","text":"** Yes, because both methods share the same name."},{"letter":"B","text":"** Yes, because int converts to double automatically."},{"letter":"C","text":"** No, because their parameter types differ."},{"letter":"D","text":"** No, because subclasses cannot declare methods."},{"letter":"E","text":"** No, because printName must return a value."}],"answer":"C","answerText":"No, because their parameter types differ.","explanation":"Overriding requires the exact same parameter types; different parameters result in method overloading."},{"id":8,"partId":1,"partTitle":"Part 1: Inheritance, Abstract Classes & Overloading","prompt":"The superclass declares printName(double), while Spider declares printName(int). What Java feature do these two declarations demonstrate?","code":null,"choices":[{"letter":"A","text":"** Method overloading across an inheritance hierarchy"},{"letter":"B","text":"** Constructor chaining between two classes"},{"letter":"C","text":"** Field hiding between related classes"},{"letter":"D","text":"** Interface implementation by a subclass"},{"letter":"E","text":"** Exception handling with overloaded catches"}],"answer":"A","answerText":"Method overloading across an inheritance hierarchy","explanation":"Defining methods with the same name but different parameter types across superclass and subclass is method overloading."},{"id":9,"partId":1,"partTitle":"Part 1: Inheritance, Abstract Classes & Overloading","prompt":"Suppose the incomplete Spider method prints \"Spider\". If a Spider object receives a call printName(4), which method is selected based on the visible signatures?","code":null,"choices":[{"letter":"A","text":"** The Spider method with an int parameter"},{"letter":"B","text":"** The Arthropod method with a double parameter"},{"letter":"C","text":"** Both methods execute in superclass order"},{"letter":"D","text":"** Neither method can accept the argument"},{"letter":"E","text":"** The constructor method executes instead"}],"answer":"A","answerText":"The Spider method with an int parameter","explanation":"The argument 4 is an int, matching the Spider method signature printName(int) exactly."},{"id":10,"partId":1,"partTitle":"Part 1: Inheritance, Abstract Classes & Overloading","prompt":"A programmer wants the Beetle class in the first code sample to compile as a concrete class while preserving its inheritance structure. Which change is sufficient?","code":null,"choices":[{"letter":"A","text":"** Implement getNumberOfSections() in Beetle."},{"letter":"B","text":"** Remove getNumberOfLegs() from Insect."},{"letter":"C","text":"** Change Insect from abstract to final."},{"letter":"D","text":"** Remove the HasExoskeleton interface."},{"letter":"E","text":"** Change Beetle into an interface."}],"answer":"A","answerText":"Implement getNumberOfSections() in Beetle.","explanation":"Beetle already implements getNumberOfLegs(); implementing getNumberOfSections() completes all abstract methods."},{"id":11,"partId":2,"partTitle":"Part 2: Abstract Classes vs. Interfaces Foundations","prompt":"Which feature is common to both abstract classes and interfaces in Java?","code":null,"choices":[{"letter":"A","text":"** They can contain public static final variables"},{"letter":"B","text":"** They must contain only abstract methods"},{"letter":"C","text":"** They cannot contain any static methods"},{"letter":"D","text":"** They must be instantiated directly"}],"answer":"A","answerText":"They can contain public static final variables","explanation":"Both abstract classes and interfaces can declare constants (public static final fields)."},{"id":12,"partId":2,"partTitle":"Part 2: Abstract Classes vs. Interfaces Foundations","prompt":"Which keyword is used when one interface inherits from another interface?","code":null,"choices":[{"letter":"A","text":"** extends"},{"letter":"B","text":"** implements"},{"letter":"C","text":"** inherits"},{"letter":"D","text":"** super"}],"answer":"A","answerText":"extends","explanation":"An interface inherits from another interface using the extends keyword."},{"id":13,"partId":2,"partTitle":"Part 2: Abstract Classes vs. Interfaces Foundations","prompt":"Why can neither an abstract class nor an interface be instantiated directly?","code":null,"choices":[{"letter":"A","text":"** They may contain unimplemented methods"},{"letter":"B","text":"** They are always declared final"},{"letter":"C","text":"** They cannot contain variables"},{"letter":"D","text":"** They must inherit from an interface"}],"answer":"A","answerText":"They may contain unimplemented methods","explanation":"Abstract classes and interfaces can contain abstract methods without bodies, so they cannot be instantiated directly."},{"id":14,"partId":2,"partTitle":"Part 2: Abstract Classes vs. Interfaces Foundations","prompt":"A concrete subclass extends an abstract class that declares three abstract methods. What must the concrete subclass do to compile?","code":"A concrete subclass extends an abstract class that declares three abstract methods. What must the concrete subclass do to","choices":[{"letter":"A","text":"** Implement all three inherited abstract methods"},{"letter":"B","text":"** Declare all three methods as static"},{"letter":"C","text":"** Convert the superclass into an interface"},{"letter":"D","text":"** Instantiate the abstract superclass first"}],"answer":"A","answerText":"Implement all three inherited abstract methods","explanation":"A concrete subclass must provide implementations for every inherited abstract method."},{"id":15,"partId":2,"partTitle":"Part 2: Abstract Classes vs. Interfaces Foundations","prompt":"Which statement correctly distinguishes a concrete subclass from an abstract subclass?","code":null,"choices":[{"letter":"A","text":"** concrete subclass provides implementations for inherited abstract methods"},{"letter":"B","text":"** concrete subclass cannot override inherited methods"},{"letter":"C","text":"** concrete subclass must always be declared final"},{"letter":"D","text":"** concrete subclass cannot implement an interface"}],"answer":"A","answerText":"A concrete subclass provides implementations for inherited abstract methods","explanation":"Concrete subclasses cannot leave any inherited abstract methods unimplemented."},{"id":16,"partId":2,"partTitle":"Part 2: Abstract Classes vs. Interfaces Foundations","prompt":"Which type can replace the blank in '____ frog = new TurtleFrog();' so the assignment compiles?","code":"public interface CanHop {}\npublic class Frog implements CanHop {}\npublic class HornedFrog extends Frog {}\npublic class TurtleFrog extends Frog {}\n\npublic class Test {\n    public static void main(String[] args) {\n        ____ frog = new TurtleFrog();\n    }\n}","choices":[{"letter":"A","text":"** Frog"},{"letter":"B","text":"** HornedFrog"},{"letter":"C","text":"** CanHop"},{"letter":"D","text":"** String"}],"answer":"A","answerText":"A or C (Frog or CanHop)","explanation":"Both Frog and CanHop are valid supertypes of TurtleFrog and allow the assignment to compile."},{"id":17,"partId":2,"partTitle":"Part 2: Abstract Classes vs. Interfaces Foundations","prompt":"Using the declarations 'Frog implements CanHop' and 'TurtleFrog extends Frog', which statement best explains why 'CanHop frog = new TurtleFrog();' compiles?","code":"public interface CanHop {}\npublic class Frog implements CanHop {}\npublic class TurtleFrog extends Frog {}\n\nCanHop frog = new TurtleFrog();","choices":[{"letter":"A","text":"** TurtleFrog inherits Frog's implementation of CanHop"},{"letter":"B","text":"** CanHop is a superclass of TurtleFrog"},{"letter":"C","text":"** Interfaces can be instantiated through any constructor"},{"letter":"D","text":"** TurtleFrog automatically becomes a String"}],"answer":"A","answerText":"TurtleFrog inherits Frog's implementation of CanHop","explanation":"Through inheritance from Frog, TurtleFrog is also an instance of CanHop."},{"id":18,"partId":2,"partTitle":"Part 2: Abstract Classes vs. Interfaces Foundations","prompt":"A class implements an interface containing 'public abstract void makeSound();. What must a concrete implementing class provide?","code":null,"choices":[{"letter":"A","text":"** public method named makeSound with no return value"},{"letter":"B","text":"** private method named makeSound returning String"},{"letter":"C","text":"** static method named makeSound returning boolean"},{"letter":"D","text":"** constructor named makeSound with no parameters"}],"answer":"A","answerText":"A public method named makeSound with no return value","explanation":"Implementing methods cannot reduce visibility (must be public) and must match the void return type."},{"id":19,"partId":2,"partTitle":"Part 2: Abstract Classes vs. Interfaces Foundations","prompt":"A programmer wants to create a subclass that inherits an abstract method but does not implement it yet. Which declaration is appropriate?","code":null,"choices":[{"letter":"A","text":"** Declare the subclass abstract"},{"letter":"B","text":"** Declare the subclass final"},{"letter":"C","text":"** Declare the subclass static"},{"letter":"D","text":"** Declare the subclass private"}],"answer":"A","answerText":"Declare the subclass abstract","explanation":"If a subclass does not implement an inherited abstract method, it must be declared abstract."},{"id":20,"partId":2,"partTitle":"Part 2: Abstract Classes vs. Interfaces Foundations","prompt":"Suppose a concrete subclass inherits one abstract method from a superclass and also inherits one abstract method from an interface. What is required for successful compilation?","code":null,"choices":[{"letter":"A","text":"** The subclass must implement both abstract methods"},{"letter":"B","text":"** The subclass must implement only the superclass method"},{"letter":"C","text":"** The subclass must implement only the interface method"},{"letter":"D","text":"** The subclass must declare itself as an interface"}],"answer":"A","answerText":"The subclass must implement both abstract methods","explanation":"A concrete class must implement all inherited abstract methods from both superclasses and interfaces."},{"id":21,"partId":3,"partTitle":"Part 3: Interface Inheritance & Default Methods","prompt":"What does the declaration public interface CanBark extends HasVocalCords indicate about CanBark?","code":null,"choices":[{"letter":"A","text":"** It inherits the method declarations from HasVocalCords"},{"letter":"B","text":"** It inherits only private methods from HasVocalCords"},{"letter":"C","text":"** It prevents classes from implementing HasVocalCords"},{"letter":"D","text":"** It must be declared as an abstract class instead"}],"answer":"A","answerText":"It inherits the method declarations from HasVocalCords","explanation":"A child interface inherits all method signatures from its parent interface."},{"id":22,"partId":3,"partTitle":"Part 3: Interface Inheritance & Default Methods","prompt":"Given the following declarations:\nWhich methods must a concrete class implementing CanBark provide?","code":"interface HasVocalCords {\n    void makeSound();\n}\ninterface CanBark extends HasVocalCords {\n    void bark();\n}","choices":[{"letter":"A","text":"** Only bark()"},{"letter":"B","text":"** Only makeSound()"},{"letter":"C","text":"** Both makeSound() and bark()"},{"letter":"D","text":"** Neither method because interfaces provide implementations"}],"answer":"C","answerText":"Both makeSound() and bark()","explanation":"A concrete class implementing CanBark must fulfill all methods from CanBark and HasVocalCords."},{"id":23,"partId":3,"partTitle":"Part 3: Interface Inheritance & Default Methods","prompt":"Which pair of modifiers is implicitly applied to an ordinary abstract method declared in a Java interface?","code":null,"choices":[{"letter":"A","text":"** public and abstract"},{"letter":"B","text":"** protected and static"},{"letter":"C","text":"** private and default"},{"letter":"D","text":"** public and static"}],"answer":"A","answerText":"public and abstract","explanation":"Ordinary methods in Java interfaces are implicitly public and abstract."},{"id":24,"partId":3,"partTitle":"Part 3: Interface Inheritance & Default Methods","prompt":"What value is printed by this program?","code":"interface Nocturnal {\n    default boolean isBlind() {\n        return true;\n    }\n}\npublic class Owl implements Nocturnal {\n    public boolean isBlind() {\n        return false;\n    }\n    public static void main(String[] args) {\n        Nocturnal nocturnal = (Nocturnal) new Owl();\n        System.out.print(nocturnal.isBlind());\n    }\n}","choices":[{"letter":"A","text":"** true"},{"letter":"B","text":"** false"},{"letter":"C","text":"** Compile error at the default method"},{"letter":"D","text":"** Compile error at the cast"}],"answer":"B","answerText":"false","explanation":"Polymorphism ensures that the overridden method in Owl executes at runtime."},{"id":25,"partId":3,"partTitle":"Part 3: Interface Inheritance & Default Methods","prompt":"What is printed by this program?","code":"class Arthropod {\n    public void printName(double input) {\n        System.out.print(\"Arthropod\");\n    }\n}\nclass Spider extends Arthropod {\n    public void printName(int input) {\n        System.out.print(\"Spider\");\n    }\n    public static void main(String[] args) {\n        Spider spider = new Spider();\n        spider.printName(4.0);\n        spider.printName(9);\n    }\n}","choices":[{"letter":"A","text":"** SpiderArthropod"},{"letter":"B","text":"** ArthropodSpider"},{"letter":"C","text":"** ArthropodArthropod"},{"letter":"C","text":"** SpiderSpider"}],"answer":"B","answerText":"ArthropodSpider","explanation":"spider.printName(4.0) calls printName(double) in Arthropod; spider.printName(9) calls printName(int) in Spider."},{"id":26,"partId":3,"partTitle":"Part 3: Interface Inheritance & Default Methods","prompt":"In the Spider program, why does spider.printName(4.0) call the method declared in Arthropod rather than the method declared in Spider?","code":null,"choices":[{"letter":"A","text":"** The double argument matches Arthropod's parameter exactly"},{"letter":"B","text":"** The subclass method always runs before superclass methods"},{"letter":"C","text":"** Java converts every double argument into an int"},{"letter":"D","text":"** The Spider method is hidden because it is public"}],"answer":"A","answerText":"The double argument matches Arthropod's parameter exactly","explanation":"4.0 is a double literal, matching printName(double)."},{"id":27,"partId":3,"partTitle":"Part 3: Interface Inheritance & Default Methods","prompt":"Suppose the statement 'spider.printName(9);' in the Spider program is changed to 'spider.printName(9.0);'. What will be printed by the two calls, in order? spider.printName(4.0); spider.printName(9.0);","code":"spider.printName(4.0);\nspider.printName(9.0);","choices":[{"letter":"A","text":"** ArthropodSpider"},{"letter":"B","text":"** SpiderArthropod"},{"letter":"C","text":"** ArthropodArthropod"},{"letter":"D","text":"** SpiderSpider"}],"answer":"C","answerText":"ArthropodArthropod","explanation":"Both 4.0 and 9.0 are doubles, so both calls invoke printName(double) in Arthropod."},{"id":28,"partId":3,"partTitle":"Part 3: Interface Inheritance & Default Methods","prompt":"A concrete class implements CanBark, where CanBark extends HasVocalCords. Neither interface supplies a default implementation. What is the most likely result if the class defines bark() but not makeSound()?","code":null,"choices":[{"letter":"A","text":"** The class fails to compile because makeSound() is unimplemented"},{"letter":"B","text":"** The class compiles and inherits makeSound() automatically"},{"letter":"C","text":"** The class runs but throws an error only when barking"},{"letter":"D","text":"** The interface hierarchy is ignored by the compiler"}],"answer":"A","answerText":"The class fails to compile because makeSound() is unimplemented","explanation":"A concrete class must implement all inherited abstract methods in the interface hierarchy."},{"id":29,"partId":3,"partTitle":"Part 3: Interface Inheritance & Default Methods","prompt":"Consider the following declarations:\nA class implementing that interface declares:\nWhich implementation is selected when an object of the class invokes isBlind()?","code":"interface Nocturnal {\n    default boolean isBlind() {\n        return true;\n    }\n}\npublic boolean isBlind() {\n    return false;\n}","choices":[{"letter":"A","text":"** The class implementation returning false"},{"letter":"B","text":"** The interface implementation returning true"},{"letter":"C","text":"** Neither implementation; the method becomes abstract"},{"letter":"D","text":"** Both implementations execute and combine their results"}],"answer":"A","answerText":"The class implementation returning false","explanation":"A class method implementation always overrides an interface default method."},{"id":30,"partId":3,"partTitle":"Part 3: Interface Inheritance & Default Methods","prompt":"A variable has static type Arthropod and refers to a Spider object. The variable is used to call printName(4.0), where Arthropod defines printName(double) and Spider defines only printName(int). Which method is selected?","code":null,"choices":[{"letter":"A","text":"** Arthropod's printName(double) method"},{"letter":"B","text":"** Spider's printName(int) method"},{"letter":"C","text":"** Both methods execute in sequence"},{"letter":"D","text":"** The call produces a compile-time error"}],"answer":"A","answerText":"Arthropod's printName(double) method","explanation":"Spider only overloads printName(int); the reference type Arthropod calls printName(double)."},{"id":31,"partId":4,"partTitle":"Part 4: Interface Modifiers, Final Methods & Object State","prompt":"What modifiers are implicitly applied to every variable declared in a Java interface?","code":null,"choices":[{"letter":"A","text":"** public, static, and final"},{"letter":"B","text":"** protected, static, and final"},{"letter":"C","text":"** private, static, and final"},{"letter":"D","text":"** public, abstract, and final"}],"answer":"A","answerText":"public, static, and final","explanation":"All variables declared in an interface are implicitly constants: public, static, and final."},{"id":32,"partId":4,"partTitle":"Part 4: Interface Modifiers, Final Methods & Object State","prompt":"Which statement correctly describes a concrete subclass in Java?","code":null,"choices":[{"letter":"A","text":"** It must implement inherited abstract methods"},{"letter":"B","text":"** It must declare every inherited method final"},{"letter":"C","text":"** It must contain at least one abstract method"},{"letter":"D","text":"** It must implement every interface default method"}],"answer":"A","answerText":"It must implement inherited abstract methods","explanation":"A concrete subclass cannot contain any unimplemented abstract methods."},{"id":33,"partId":4,"partTitle":"Part 4: Interface Modifiers, Final Methods & Object State","prompt":"Why can an abstract class not be instantiated directly?","code":null,"choices":[{"letter":"A","text":"** It may contain methods without implementations"},{"letter":"B","text":"** Its required to contain only static methods"},{"letter":"C","text":"** It cannot declare constructors for subclasses"},{"letter":"D","text":"** Its automatically treated as an interface"}],"answer":"A","answerText":"It may contain methods without implementations","explanation":"Abstract classes represent incomplete types and cannot be instantiated directly."},{"id":34,"partId":4,"partTitle":"Part 4: Interface Modifiers, Final Methods & Object State","prompt":"Which statement about methods in Java interfaces is correct?","code":null,"choices":[{"letter":"A","text":"** An interface may contain default and static methods"},{"letter":"B","text":"** Every interface method must remain abstract"},{"letter":"C","text":"** An interface may contain protected instance methods"},{"letter":"D","text":"** Every interface method must be declared final"}],"answer":"A","answerText":"An interface may contain default and static methods","explanation":"Since Java 8, interfaces can define default and static methods with concrete bodies."},{"id":35,"partId":4,"partTitle":"Part 4: Interface Modifiers, Final Methods & Object State","prompt":"Consider this Java code:\nWhat happens when this code is compiled?","code":"class Reptile {\npublic final void layEggs() {\nSystem.out.print( Reptile Laying Eggs');\n}\n}\nclass Lizard extends Reptile {\npublic void layEggs() {\nSystem.out.print(\"Lizard Laying Eggs'):\n}\n}","choices":[{"letter":"A","text":"** It produces the reptile message"},{"letter":"B","text":"** It produces the lizard message"},{"letter":"C","text":"** It reports an error in the overnde"},{"letter":"D","text":"** It reports an error when creating Lizard"}],"answer":"C","answerText":"It reports an error in the override","explanation":"A final method in a superclass cannot be overridden by a subclass."},{"id":36,"partId":4,"partTitle":"Part 4: Interface Modifiers, Final Methods & Object State","prompt":"Suppose the method layEggs() in Reptile were not declared final. For the following statements, what would be printed?","code":"Reptile reptile = new Lizard();\nreptile.layEggs();","choices":[{"letter":"A","text":"** Reptile Laying Eggs"},{"letter":"B","text":"** Lizard Laying Eggs"},{"letter":"C","text":"** No message is printed"},{"letter":"D","text":"** The code cannot compile"}],"answer":"B","answerText":"Lizard Laying Eggs","explanation":"When layEggs() is not final, Lizard overrides it and polymorphism calls Lizard's method."},{"id":37,"partId":4,"partTitle":"Part 4: Interface Modifiers, Final Methods & Object State","prompt":"What is printed by this Java program?","code":"abstract class Whale {\n    public abstract void dive();\n}\nclass Orca extends Whale {\n    public void dive() {\n        System.out.print(\"Orca diving\");\n    }\n}\n// in main:\nWhale whale = new Orca();\nwhale.dive();","choices":[{"letter":"A","text":"** Whale diving"},{"letter":"B","text":"** Orca diving"},{"letter":"C","text":"** No output is produced"},{"letter":"D","text":"** compile error is produced"}],"answer":"B","answerText":"Orca diving","explanation":"whale refers to an Orca instance; calling whale.dive() executes Orca's dive() method."},{"id":38,"partId":4,"partTitle":"Part 4: Interface Modifiers, Final Methods & Object State","prompt":"A developer needs a parent type that can provide shared instance state and implemented behavior while also requiring subclasses to implement selected methods. Which design best fits this requirement?","code":null,"choices":[{"letter":"A","text":"** An abstract class with fields and abstract methods"},{"letter":"B","text":"** An interface containing only constant variables"},{"letter":"C","text":"** A concrete class containing only abstract methods"},{"letter":"D","text":"** A static utility class containing default methods"}],"answer":"A","answerText":"An abstract class with fields and abstract methods","explanation":"Only classes can maintain instance fields (shared instance state) while enforcing abstract methods."},{"id":39,"partId":4,"partTitle":"Part 4: Interface Modifiers, Final Methods & Object State","prompt":"A class implements an interface that provides a default implementation for a method. What must the class do?","code":null,"choices":[{"letter":"A","text":"** It must always override the default method"},{"letter":"B","text":"** It may use the default implementation without overriding"},{"letter":"C","text":"** It must declare the method as private and final"},{"letter":"D","text":"** It must convert the interface into an abstract class"}],"answer":"B","answerText":"It may use the default implementation without overriding","explanation":"A class implementing an interface inherits its default methods automatically."},{"id":40,"partId":4,"partTitle":"Part 4: Interface Modifiers, Final Methods & Object State","prompt":"Which statement accurately compares Java abstract classes and interfaces?","code":null,"choices":[{"letter":"A","text":"** Both can be instantiated directly by subclasses"},{"letter":"B","text":"** Both can declare public static final variables"},{"letter":"C","text":"** Both inherit implementation from java.lang Object"},{"letter":"D","text":"** Both require every method to be abstract"}],"answer":"B","answerText":"Both can declare public static final variables","explanation":"Both abstract classes and interfaces can define public static final constant fields."},{"id":41,"partId":5,"partTitle":"Part 5: Class Extension, Constructors & Overloading","prompt":"Which statement about a concrete subclass is correct?","code":null,"choices":[{"letter":"A","text":"** It may be declared abstract or final"},{"letter":"B","text":"** It must always be declared abstract"},{"letter":"C","text":"** It cannot be declared final"},{"letter":"D","text":"** It must implement another interface"}],"answer":"A","answerText":"It may be declared abstract or final","explanation":"A concrete subclass can be declared final to prevent further extension."},{"id":42,"partId":5,"partTitle":"Part 5: Class Extension, Constructors & Overloading","prompt":"What must a concrete subclass do when it inherits an abstract method from a superclass or interface?","code":null,"choices":[{"letter":"A","text":"** Override the method with an implementation"},{"letter":"B","text":"** Declare the method as private"},{"letter":"C","text":"** Remove the method from the parent type"},{"letter":"D","text":"** Convert the method into a constructor"}],"answer":"A","answerText":"Override the method with an implementation","explanation":"A concrete class must provide a concrete implementation for any inherited abstract method."},{"id":43,"partId":5,"partTitle":"Part 5: Class Extension, Constructors & Overloading","prompt":"Which declaration correctly shows one interface extending another interface?","code":null,"choices":[{"letter":"A","text":"** interface CanBark extends HasVocalCords { }"},{"letter":"B","text":"** interface CanBark implements HasVocalCords { }"},{"letter":"C","text":"** class CanBark extends HasVocalCords { }"},{"letter":"D","text":"** interface HasVocalCords extends CanBark { }"}],"answer":"A","answerText":"interface CanBark extends HasVocalCords { }","explanation":"An interface inherits another interface using the extends keyword."},{"id":44,"partId":5,"partTitle":"Part 5: Class Extension, Constructors & Overloading","prompt":"What methods must a concrete class that implements CanBark provide?","code":"interface HasVocalCords {\n    void makeSound();\n}\ninterface CanBark extends HasVocalCords {\n    void bark();\n}","choices":[{"letter":"A","text":"** Implement both makeSound() and bark()"},{"letter":"B","text":"** Implement only makeSound()"},{"letter":"C","text":"** Implement only bark()"},{"letter":"D","text":"** Implement neither inherited method"}],"answer":"A","answerText":"Implement both makeSound() and bark()","explanation":"A concrete class implementing CanBark must implement all methods from CanBark and HasVocalCords."},{"id":45,"partId":5,"partTitle":"Part 5: Class Extension, Constructors & Overloading","prompt":"An abstract class implements HasVocalCords, which declares void makeSound(). What is true if the abstract class does not implement that method?","code":null,"choices":[{"letter":"A","text":"** The abstract class may leave it unimplemented"},{"letter":"B","text":"** The interface declaration becomes invalid"},{"letter":"C","text":"** The class must become final"},{"letter":"D","text":"** The method is automatically made static"}],"answer":"A","answerText":"The abstract class may leave it unimplemented","explanation":"An abstract class can defer implementing interface methods to its subclasses."},{"id":46,"partId":5,"partTitle":"Part 5: Class Extension, Constructors & Overloading","prompt":"What happens when an interface extends another interface in Java?","code":null,"choices":[{"letter":"A","text":"** The child interface inherits the parent interface's method requirements"},{"letter":"B","text":"** The parent interface becomes a concrete class"},{"letter":"C","text":"** The child interface must use implements instead"},{"letter":"D","text":"** The parent interface loses all declared methods"}],"answer":"A","answerText":"The child interface inherits the parent interface's method requirements","explanation":"The sub-interface inherits all method contracts from the parent interface."},{"id":47,"partId":5,"partTitle":"Part 5: Class Extension, Constructors & Overloading","prompt":"Why does this code fail to compile?","code":"class Mammal {\n    public Mammal(int age) {\n        System.out.print(\"Mammal\");\n    }\n}\npublic class Platypus extends Mammal {\n    public Platypus() {\n        System.out.print(\"Platypus\");\n    }\n}","choices":[{"letter":"A","text":"** The constructor implicitly calls unavailable Mammal()"},{"letter":"B","text":"** The subclass cannot contain a no-argument constructor"},{"letter":"C","text":"** The print statement must appear after construction"},{"letter":"D","text":"** subclass cannot extend a class with parameters"}],"answer":"A","answerText":"The constructor implicitly calls unavailable Mammal()","explanation":"Platypus implicitly calls super(), but Mammal has no no-argument constructor."},{"id":48,"partId":5,"partTitle":"Part 5: Class Extension, Constructors & Overloading","prompt":"How can the Platypus constructor be corrected so that it can invoke the available superclass constructor?","code":null,"choices":[{"letter":"A","text":"** Use super(0); before the print statement"},{"letter":"B","text":"** Use this(0); after the print statement"},{"letter":"C","text":"** Add final before the constructor"},{"letter":"D","text":"** Replace extends with implements"}],"answer":"A","answerText":"Use super(0); before the print statement","explanation":"Explicitly calling super(0); invokes the available Mammal(int age) constructor."},{"id":49,"partId":5,"partTitle":"Part 5: Class Extension, Constructors & Overloading","prompt":"Assume the Mammal class has a valid no-argument constructor. When new Platypus() is executed and the superclass constructor prints \"Mammal\" while the subclass constructor prints Platypus', what is printed?","code":null,"choices":[{"letter":"A","text":"** MammalPlatypus"},{"letter":"B","text":"** PlatypusMammal"},{"letter":"C","text":"** Mammal only"},{"letter":"D","text":"** Platypus only"}],"answer":"A","answerText":"MammalPlatypus","explanation":"The superclass constructor executes first, followed by the subclass constructor."},{"id":50,"partId":5,"partTitle":"Part 5: Class Extension, Constructors & Overloading","prompt":"Which statement best describes the relationship between the two methods?","code":"interface Aquatic {\n    default int getNumberOfGills(int input) {\n        return 2;\n    }\n}\nclass ClownFish implements Aquatic {\n    public int getNumberOfGills() {\n        return 4;\n    }\n}","choices":[{"letter":"A","text":"** They are overloaded because their parameter lists differ"},{"letter":"B","text":"** The class method overrides the default method"},{"letter":"C","text":"** The class fails because interfaces cannot have defaults"},{"letter":"D","text":"** The class method replaces the default method despite different parameters"}],"answer":"A","answerText":"They are overloaded because their parameter lists differ","explanation":"getNumberOfGills(int) and getNumberOfGills() have different parameter lists, so they are overloaded."},{"id":51,"partId":6,"partTitle":"Part 6: Interface Access Rules, Visibility & Polymorphism","prompt":"For an abstract method declared in a Java interface, which access modifier is implicitly applied?","code":null,"choices":[{"letter":"A","text":"** public"},{"letter":"B","text":"** protected"},{"letter":"C","text":"** private"},{"letter":"D","text":"** package-private"}],"answer":"A","answerText":"public","explanation":"Abstract methods in interfaces are implicitly public."},{"id":52,"partId":6,"partTitle":"Part 6: Interface Access Rules, Visibility & Polymorphism","prompt":"What does the default keyword provide for a method in a Java interface?","code":null,"choices":[{"letter":"A","text":"** method implementation"},{"letter":"B","text":"** private constructor"},{"letter":"C","text":"** static field"},{"letter":"D","text":"** An abstract class"}],"answer":"A","answerText":"A method implementation","explanation":"The default keyword allows an interface method to supply a concrete body."},{"id":53,"partId":6,"partTitle":"Part 6: Interface Access Rules, Visibility & Polymorphism","prompt":"Given the interface:\nWhat value does the default method return?","code":"interface Nocturnal {\n    default boolean isBlind() {\n        return true;\n    }\n}","choices":[{"letter":"A","text":"** true"},{"letter":"B","text":"** false"},{"letter":"C","text":"** 0"},{"letter":"D","text":"** null"}],"answer":"A","answerText":"true","explanation":"The default method explicitly returns true."},{"id":54,"partId":6,"partTitle":"Part 6: Interface Access Rules, Visibility & Polymorphism","prompt":"A class named Owl implements Nocturnal and overrides isBlind() to return false. If a Nocturnal reference refers to an Owl object, what does nocturnal.isBlind() return?","code":null,"choices":[{"letter":"A","text":"** false"},{"letter":"B","text":"** true"},{"letter":"C","text":"** null"},{"letter":"D","text":"** compile-time error"}],"answer":"A","answerText":"false","explanation":"Polymorphism calls the overridden method in Owl, which returns false."},{"id":55,"partId":6,"partTitle":"Part 6: Interface Access Rules, Visibility & Polymorphism","prompt":"Why does the call nocturnalisBlind() use Owl's implementation rather than the interface default implementation?","code":null,"choices":[{"letter":"A","text":"** The object overrides the method"},{"letter":"B","text":"** The reference hides the method"},{"letter":"C","text":"** The cast changes the method"},{"letter":"D","text":"** The interface is abstract"}],"answer":"A","answerText":"The object overrides the method","explanation":"The runtime object Owl overrides the default interface method."},{"id":56,"partId":6,"partTitle":"Part 6: Interface Access Rules, Visibility & Polymorphism","prompt":"What is the result of assigning a newly created Owl object to a Nocturnal reference?","code":null,"choices":[{"letter":"A","text":"** The assignment is valid"},{"letter":"B","text":"** The assignment needs inheritance"},{"letter":"C","text":"** The assignment causes an error"},{"letter":"D","text":"** The assignment creates two objects"}],"answer":"A","answerText":"The assignment is valid","explanation":"Owl implements Nocturnal, so assigning an Owl instance to a Nocturnal reference is a valid upcast."},{"id":57,"partId":6,"partTitle":"Part 6: Interface Access Rules, Visibility & Polymorphism","prompt":"In Nocturnal nocturnal = (Nocturnal) new Owl();, what is the main effect of the explicit cast?","code":null,"choices":[{"letter":"A","text":"** It treats the object as Nocturnal"},{"letter":"B","text":"** It converts the object to text"},{"letter":"C","text":"** It invokes the default method"},{"letter":"D","text":"** It changes the object's class"}],"answer":"A","answerText":"It treats the object as Nocturnal","explanation":"The cast treats the object through the Nocturnal reference type."},{"id":58,"partId":6,"partTitle":"Part 6: Interface Access Rules, Visibility & Polymorphism","prompt":"If Owl did not override isBlind(), what would new Owl().isBlind() return when the inherited interface default method is used?","code":null,"choices":[{"letter":"A","text":"** true"},{"letter":"B","text":"** false"},{"letter":"C","text":"** 8"},{"letter":"D","text":"** compile-time error"}],"answer":"A","answerText":"true","explanation":"If not overridden, the inherited default method in Nocturnal returns true."},{"id":59,"partId":6,"partTitle":"Part 6: Interface Access Rules, Visibility & Polymorphism","prompt":"The method getNumberOfGills(int input) always returns the string \"8\". What does getNumberOfGills(-1) return?","code":null,"choices":[{"letter":"A","text":"** \"8\""},{"letter":"B","text":"** -1"},{"letter":"C","text":"** 8"},{"letter":"D","text":"** A null value"}],"answer":"A","answerText":"\"8\"","explanation":"The method always returns the string \"8\" regardless of input."},{"id":60,"partId":6,"partTitle":"Part 6: Interface Access Rules, Visibility & Polymorphism","prompt":"Suppose Owl declares boolean isBlind() without the public modifier while implementing the interface method. What is the most likely result?","code":null,"choices":[{"letter":"A","text":"** compile-time error"},{"letter":"B","text":"** The method becomes protected"},{"letter":"C","text":"** The interface method is ignored"},{"letter":"D","text":"** The default method is called"}],"answer":"A","answerText":"compile-time error","explanation":"Interface methods are public; omitting public in the implementing class assigns weaker package-private access."},{"id":61,"partId":7,"partTitle":"Part 7: Variable Scopes, Imports & Loop Execution","prompt":"Which type of variable has a scope limited to a method or block of code?","code":null,"choices":[{"letter":"A","text":"** Interface variables"},{"letter":"B","text":"** Block variables"},{"letter":"C","text":"** Class variables"},{"letter":"D","text":"** Instance variables"}],"answer":"B","answerText":"Block variables","explanation":"Local/block variables are scoped exclusively to the block or method where they are declared."},{"id":62,"partId":7,"partTitle":"Part 7: Variable Scopes, Imports & Loop Execution","prompt":"Which type of variable is available throughout the class and can be accessed for the duration of the program?","code":null,"choices":[{"letter":"A","text":"** Interface variables"},{"letter":"B","text":"** Block variables"},{"letter":"C","text":"** Class variables"},{"letter":"D","text":"** Instance variables"}],"answer":"C","answerText":"Class variables","explanation":"Static (class) variables exist throughout the program's lifetime across all instances."},{"id":63,"partId":7,"partTitle":"Part 7: Variable Scopes, Imports & Loop Execution","prompt":"Which statement about Java import statements Is true?","code":null,"choices":[{"letter":"A","text":"** Unused imports prevent compilation."},{"letter":"B","text":"** Unused imports may be removed safely."},{"letter":"C","text":"** Duplicate imports prevent compilation."},{"letter":"D","text":"** Missing imported classes still compile."}],"answer":"B","answerText":"Unused imports may be removed safely","explanation":"Unused imports do not affect compilation or execution and can be safely removed."},{"id":64,"partId":7,"partTitle":"Part 7: Variable Scopes, Imports & Loop Execution","prompt":"Which package is imported into every Java class by default?","code":null,"choices":[{"letter":"A","text":"** java.util"},{"letter":"B","text":"** java.system"},{"letter":"C","text":"** java.lang"},{"letter":"D","text":"** java.io"}],"answer":"C","answerText":"java.lang","explanation":"The java.lang package is imported automatically into every Java class."},{"id":65,"partId":7,"partTitle":"Part 7: Variable Scopes, Imports & Loop Execution","prompt":"Which loop iterates a different number of times from the other three?","code":null,"choices":[{"letter":"A","text":"** for (int i = 0; i < 5; i++)"},{"letter":"B","text":"** for (int i = 1; i <= 5; i++)"},{"letter":"C","text":"** int k = 0; do {} while (k++ < 5);"},{"letter":"D","text":"** int k = 0; while (k++ < 5) {}"}],"answer":"C","answerText":"int k=0; do {} while (k++ < 5);","explanation":"The do-while loop executes 6 times (checking k from 0 to 5), while the other loops execute 5 times."},{"id":66,"partId":7,"partTitle":"Part 7: Variable Scopes, Imports & Loop Execution","prompt":"What is the output of this Java code?","code":"for (int x = 0; x < 5; x++) {\n    System.out.print(1);\n    if (x < 2) continue;\n    else break;\n}","choices":[{"letter":"A","text":"** 111"},{"letter":"B","text":"** 1"},{"letter":"C","text":"** 11"},{"letter":"D","text":"** 1111"},{"letter":"E","text":"** The code produces no output"}],"answer":"A","answerText":"111","explanation":"Prints '1' for x = 0 (continue), x = 1 (continue), and x = 2 (break)."},{"id":67,"partId":7,"partTitle":"Part 7: Variable Scopes, Imports & Loop Execution","prompt":"Which declaration is a reference variable rather than a primitive variable in Java?","code":null,"choices":[{"letter":"A","text":"** inti"},{"letter":"B","text":"** longl;"},{"letter":"C","text":"** String[] strings;"},{"letter":"D","text":"** double d;"}],"answer":"C","answerText":"String[] strings;","explanation":"Arrays in Java are reference types; the other options are primitive types."},{"id":68,"partId":7,"partTitle":"Part 7: Variable Scopes, Imports & Loop Execution","prompt":"What kind of member is declared by static int ii; inside a Java class?","code":null,"choices":[{"letter":"A","text":"** An instance field"},{"letter":"B","text":"** class field"},{"letter":"C","text":"** Alocal variable"},{"letter":"D","text":"** A method parameter"}],"answer":"B","answerText":"A class field","explanation":"static int ii; declares a static variable (class field)."},{"id":69,"partId":7,"partTitle":"Part 7: Variable Scopes, Imports & Loop Execution","prompt":"How many times does this loop body execute?","code":"for(inti=0;i<5;i++) {}","choices":[{"letter":"A","text":"** Four times"},{"letter":"B","text":"** Five times"},{"letter":"C","text":"** Six times"},{"letter":"D","text":"** Zero times"}],"answer":"B","answerText":"Five times","explanation":"The loop runs for i = 0, 1, 2, 3, 4 (5 iterations)."},{"id":70,"partId":7,"partTitle":"Part 7: Variable Scopes, Imports & Loop Execution","prompt":"Which statement can be inserted inside the body of this loop so that it compiles?","code":"for (int i = 0; i < 5; i++) {\n    [statement]\n}","choices":[{"letter":"A","text":"** static int j = i;"},{"letter":"B","text":"** int j = i;"},{"letter":"C","text":"** static int j = ii;"},{"letter":"D","text":"** int i = 0;"}],"answer":"B","answerText":"int j = i;","explanation":"Declaring local variable int j = i; is valid; static is illegal inside methods, and int i = 0; duplicates i."},{"id":71,"partId":8,"partTitle":"Part 8: Operators, Precedence, Control Flow & Arrays","prompt":"Which declaration can be placed directly inside the class body, outside the main method and loop?","code":null,"choices":[{"letter":"A","text":"** static int j = ii;"},{"letter":"B","text":"** static int j = i;"},{"letter":"C","text":"** int j = i;"},{"letter":"D","text":"** int j = 0; inside main"}],"answer":"A","answerText":"static int j = ii;","explanation":"Can initialize with the static class field ii; local variable i from main is out of scope."},{"id":72,"partId":8,"partTitle":"Part 8: Operators, Precedence, Control Flow & Arrays","prompt":"Why does static int j = i; fail when placed directly inside the class body if i is declared in the loop inside main?","code":null,"choices":[{"letter":"A","text":"** The loop variable has local scope"},{"letter":"B","text":"** The class field must be a String"},{"letter":"C","text":"** The loop variable is automatically final"},{"letter":"D","text":"** The class cannot contain integer fields"}],"answer":"A","answerText":"The loop variable has local scope","explanation":"The variable i declared inside main has local scope and cannot be referenced in the class body."},{"id":73,"partId":8,"partTitle":"Part 8: Operators, Precedence, Control Flow & Arrays","prompt":"Consider the following Java statements:\nWhat is the value of y immediately after the second statement executes?","code":"int y = 4;\nint x = 10 + ++y / 5;","choices":[{"letter":"A","text":"** 4"},{"letter":"B","text":"** 5"},{"letter":"C","text":"** 10"},{"letter":"D","text":"** Nn"}],"answer":"B","answerText":"5","explanation":"The pre-increment ++y increments y from 4 to 5 before evaluation."},{"id":74,"partId":8,"partTitle":"Part 8: Operators, Precedence, Control Flow & Arrays","prompt":"What does this Java program print?","code":"int y = 4;\nint x = 10 + ++y / 5;\nSystem.out.println(x % y);","choices":[{"letter":"A","text":"** 0"},{"letter":"B","text":"** 1"},{"letter":"C","text":"** 4"},{"letter":"D","text":"** 2"}],"answer":"B","answerText":"1","explanation":"x = 10 + (5 / 5) = 11; then 11 % 5 = 1."},{"id":75,"partId":8,"partTitle":"Part 8: Operators, Precedence, Control Flow & Arrays","prompt":"Which evaluation sequence correctly describes this code?","code":"int y = 4;\nint x = 10 + ++y / 5;","choices":[{"letter":"A","text":"** y becomes 5, then 5 / 5 equals 1, so x becomes 11"},{"letter":"B","text":"** y remains 4, then 4 / 5 equals 0, so x becomes 10"},{"letter":"C","text":"** y becomes 5, then 10 / 5 equals 2, so x becomes 12"},{"letter":"D","text":"** y becomes 4, then 10 / 4 equals 2, so x becomes 12"}],"answer":"A","answerText":"y becomes 5, then 5 / 5 equals 1, so x becomes 11","explanation":"Traces the exact evaluation order of pre-increment and division."},{"id":76,"partId":8,"partTitle":"Part 8: Operators, Precedence, Control Flow & Arrays","prompt":"Which change makes the loop execute six times instead of five times?","code":"for(inti=0;i<5;i++){}","choices":[{"letter":"A","text":"** Change i < 5 to i < 6"},{"letter":"B","text":"** Change i = 0 to i = 1"},{"letter":"C","text":"** Change i++ to i += 2"},{"letter":"D","text":"** Change i < 5 to i > 5"}],"answer":"A","answerText":"Change i < 5 to i < 6","explanation":"Changing the condition to i < 6 makes the loop run 6 times (0 through 5)."},{"id":77,"partId":8,"partTitle":"Part 8: Operators, Precedence, Control Flow & Arrays","prompt":"Which statement is true about primitive data types in Java?","code":null,"choices":[{"letter":"A","text":"** They can be assigned the value null"},{"letter":"B","text":"** String is one of the primitive types"},{"letter":"C","text":"** Their type names begin with lowercase letters"},{"letter":"D","text":"** Programmers can define new primitive types"}],"answer":"C","answerText":"Their type names begin with lowercase letters","explanation":"All primitive types in Java (int, double, boolean, etc.) are lowercase keywords."},{"id":78,"partId":8,"partTitle":"Part 8: Operators, Precedence, Control Flow & Arrays","prompt":"What is the first valid index of the array int[] nums = {3, 5, 7, 9}; in Java?","code":null,"choices":[{"letter":"A","text":"** Index 0, containing 3"},{"letter":"B","text":"** Index 1, containing 5"},{"letter":"C","text":"** Index 2, containing 7"},{"letter":"D","text":"** Index 3, containing 9"}],"answer":"A","answerText":"Index 0, containing 3","explanation":"Java arrays are zero-indexed, so the first element is at index 0."},{"id":79,"partId":8,"partTitle":"Part 8: Operators, Precedence, Control Flow & Arrays","prompt":"What is printed, assuming index is available after the loop?","code":"int[] nums = {3, 5, 7, 9};\nint sum = 0;\nfor (int index = 1; index < nums.length; index++) {\n    System.out.print(nums[index]);\n}\nSystem.out.print(sum / index);","choices":[{"letter":"A","text":"** 35790"},{"letter":"B","text":"** 3570"},{"letter":"C","text":"** 5790"},{"letter":"D","text":"** 570"}],"answer":"C","answerText":"5790","explanation":"The loop prints elements at indices 1, 2, 3 ('579'), and sum / index evaluates to 0 / 4 = 0 ('5790')."},{"id":80,"partId":8,"partTitle":"Part 8: Operators, Precedence, Control Flow & Arrays","prompt":"In the loop for (int index = 1; index < nums.length; index++), which array element is skipped first when nums is {3, 5, 7, 9}?","code":null,"choices":[{"letter":"A","text":"** The element containing 3"},{"letter":"B","text":"** The element containing 5"},{"letter":"C","text":"** The element containing 7"},{"letter":"D","text":"** The element containing 9"}],"answer":"A","answerText":"The element containing 3","explanation":"The loop starts at index 1, skipping index 0 (which contains 3)."},{"id":81,"partId":9,"partTitle":"Part 9: Advanced Evaluation Order, Switch & Overloading","prompt":"Why does sum / index evaluate to 0 in the array code when sum remains initialized to 0?","code":null,"choices":[{"letter":"A","text":"** Because integer division truncates every result"},{"letter":"B","text":"** Because dividing zero by a positive integer gives zero"},{"letter":"C","text":"** Because the array contains no zero values"},{"letter":"D","text":"** Because the loop changes zero into a whole number"}],"answer":"B","answerText":"Because dividing zero by a positive integer gives zero","explanation":"sum is 0, and 0 divided by any positive integer is 0."},{"id":82,"partId":9,"partTitle":"Part 9: Advanced Evaluation Order, Switch & Overloading","prompt":"What is the result of this Java code?","code":"int x = 9;\nlong y = x * (long) (++x);\nSystem.out.println(y);","choices":[{"letter":"A","text":"** The program prints -1"},{"letter":"B","text":"** The program prints 9"},{"letter":"C","text":"** The program prints 81"},{"letter":"D","text":"** The program prints 90"}],"answer":"D","answerText":"90","explanation":"Java evaluates operands left-to-right: left x is 9, then ++x increments x to 10; 9 * 10 = 90."},{"id":83,"partId":9,"partTitle":"Part 9: Advanced Evaluation Order, Switch & Overloading","prompt":"In the expression x * (long) (++x), what does the prefix increment operator do before multiplication?","code":"int x = 9;\nlong y = x * (long) (++x);","choices":[{"letter":"A","text":"** It changes x from 9 to 10."},{"letter":"B","text":"** It changes x from 10 to 9."},{"letter":"C","text":"** It multiplies x by itself first."},{"letter":"D","text":"** It converts x into a floating-point value."}],"answer":"A","answerText":"It changes x from 9 to 10.","explanation":"The prefix increment operator (++x) increments the value of x from 9 to 10 immediately before evaluating the operand and performing the multiplication (9 * 10L = 90L)."},{"id":84,"partId":9,"partTitle":"Part 9: Advanced Evaluation Order, Switch & Overloading","prompt":"Given the following Java classes, what is printed when the program runs?","code":"class Whale {\n    public void dive() { }\n}\nclass Orca extends Whale {\n    public void dive() {\n        System.out.print(\"Orca diving\");\n    }\n}\n// in main:\nWhale whale = new Orca();\nwhale.dive();","choices":[{"letter":"A","text":"** The program prints \"Whale diving\""},{"letter":"B","text":"** The program prints \"Orca diving\""},{"letter":"C","text":"** The program produces no output"},{"letter":"D","text":"** The program fails with a runtime exception"}],"answer":"B","answerText":"The program prints \"Orca diving\"","explanation":"Polymorphism ensures dynamic method dispatch: at runtime, Java executes the overridden dive() method belonging to the actual object instance (Orca), printing \"Orca diving\"."},{"id":85,"partId":9,"partTitle":"Part 9: Advanced Evaluation Order, Switch & Overloading","prompt":"A Java switch statement can contain how many case statements and default statements?","code":null,"choices":[{"letter":"A","text":"** At most one case and at least one default"},{"letter":"B","text":"** Any number of cases and at most one default"},{"letter":"C","text":"** At least one case and any number of defaults"},{"letter":"D","text":"** At least one case and at most one default"}],"answer":"B","answerText":"Any number of cases and at most one default","explanation":"In Java switch statements, you may declare 0 or more (any number of) case labels, but at most one optional default label is permitted."},{"id":86,"partId":9,"partTitle":"Part 9: Advanced Evaluation Order, Switch & Overloading","prompt":"Which statements are true about overloaded methods in Java?\nI. Overloaded methods must have the same name.\nII. Overloaded methods must have the same return type.\nIII. Overloaded methods must have a different list of parameters.","code":null,"choices":[{"letter":"A","text":"** I only"},{"letter":"B","text":"** II only"},{"letter":"C","text":"** III only"},{"letter":"D","text":"** I and III"},{"letter":"E","text":"** II and III"}],"answer":"D","answerText":"I and III","explanation":"Overloaded methods must share the same method name (Statement I) and must have different parameter lists by type, number, or order (Statement III). They are not required to have the same return type."},{"id":87,"partId":9,"partTitle":"Part 9: Advanced Evaluation Order, Switch & Overloading","prompt":"What happens when this Java code is compiled and run?","code":"public class Chicken {\n    public static void main(String[] args) {\n        layEggs(1, 2);\n        layEggs(3);\n    }\n    static void layEggs(int... eggs) {\n        System.out.print(\"many \" + eggs[0] + \" \");\n    }\n    static void layEggs(int eggs) {\n        System.out.print(\"one \" + eggs + \" \");\n    }\n}","choices":[{"letter":"A","text":"** It prints many 1 one 3"},{"letter":"B","text":"** It prints many 1 many 3"},{"letter":"C","text":"** It prints many 2 one 3"},{"letter":"D","text":"** The code fails to compile"}],"answer":"A","answerText":"It prints many 1 one 3","explanation":"Exact parameter match takes precedence over varargs. layEggs(1, 2) matches layEggs(int... eggs) printing 'many 1 ', while layEggs(3) matches the exact layEggs(int eggs) overload printing 'one 3 '."},{"id":88,"partId":9,"partTitle":"Part 9: Advanced Evaluation Order, Switch & Overloading","prompt":"Which of the following is a valid Java method name?","code":null,"choices":[{"letter":"A","text":"** go_$Outside$20()"},{"letter":"B","text":"** have-Fun()"},{"letter":"C","text":"** new()"},{"letter":"D","text":"** 9EnjoyTheWeather()"},{"letter":"E","text":"** class()"}],"answer":"A","answerText":"go_$Outside$20()","explanation":"Java identifiers can contain letters, digits, underscores (_), and dollar signs ($), but cannot start with a digit (9), contain hyphens (-), or be reserved keywords (new, class)."},{"id":89,"partId":9,"partTitle":"Part 9: Advanced Evaluation Order, Switch & Overloading","prompt":"Which declaration correctly uses Java's varargs syntax for a parameter named x of type int?","code":null,"choices":[{"letter":"A","text":"** ...int x"},{"letter":"B","text":"** int... x"},{"letter":"C","text":"** int...x()"},{"letter":"D","text":"** int x..."},{"letter":"E","text":"** varargs int x"}],"answer":"B","answerText":"int... x","explanation":"Java varargs syntax places three dots (...) immediately after the type name (e.g. int... x) as the final parameter in a method signature."},{"id":90,"partId":9,"partTitle":"Part 9: Advanced Evaluation Order, Switch & Overloading","prompt":"Java uses which mechanism to send data into a method?","code":null,"choices":[{"letter":"A","text":"** Pass-by-value"},{"letter":"B","text":"** Pass-by-reference"},{"letter":"C","text":"** Both pass-by-value and pass-by-reference"},{"letter":"D","text":"** Pass-by-null"}],"answer":"A","answerText":"Pass-by-value","explanation":"Java is strictly pass-by-value in all cases: primitive values are copied directly, and object reference values (pointers to objects) are passed by value."},{"id":91,"partId":10,"partTitle":"Part 10: Variable Scopes (Block, Method, Instance, Class & Interface)","prompt":"Which type of Java variable has a scope limited to a method?","code":null,"choices":[{"letter":"A","text":"** Interface variable"},{"letter":"B","text":"** Block / Local variable"},{"letter":"C","text":"** Class variable"},{"letter":"D","text":"** Instance variable"}],"answer":"B","answerText":"Block / Local variable","explanation":"Local variables declared within a method or block exist only within that method/block execution and cannot be accessed outside."},{"id":92,"partId":10,"partTitle":"Part 10: Variable Scopes (Block, Method, Instance, Class & Interface)","prompt":"Which type of Java variable is considered to remain in scope for the entire program execution?","code":null,"choices":[{"letter":"A","text":"** Interface variable"},{"letter":"B","text":"** Block variable"},{"letter":"C","text":"** Class variable (static)"},{"letter":"D","text":"** Instance variable"}],"answer":"C","answerText":"Class variable (static)","explanation":"Class variables (static fields) are loaded when the class is initialized and remain in scope for the entire lifecycle of the Java Virtual Machine program."},{"id":93,"partId":10,"partTitle":"Part 10: Variable Scopes (Block, Method, Instance, Class & Interface)","prompt":"What is the main purpose of defining a variable's scope in Java?","code":null,"choices":[{"letter":"A","text":"** To limit variable access and prevent unauthorized modification"},{"letter":"B","text":"** To increase variable size in memory"},{"letter":"C","text":"** To determine variable syntax color"},{"letter":"D","text":"** To prevent program execution"}],"answer":"A","answerText":"To limit variable access and prevent unauthorized modification","explanation":"Scope restricts where a variable identifier can be read or modified, preventing unwanted side-effects and promoting encapsulation and clean memory management."},{"id":94,"partId":10,"partTitle":"Part 10: Variable Scopes (Block, Method, Instance, Class & Interface)","prompt":"A variable is declared inside a small block within a method. Which scope category best describes it?","code":null,"choices":[{"letter":"A","text":"** Interface variable"},{"letter":"B","text":"** Block variable"},{"letter":"C","text":"** Class variable"},{"letter":"D","text":"** Instance variable"}],"answer":"B","answerText":"Block variable","explanation":"A variable declared inside curly braces { ... } (such as an if statement or loop block) has block scope and exists only within those braces."},{"id":95,"partId":10,"partTitle":"Part 10: Variable Scopes (Block, Method, Instance, Class & Interface)","prompt":"A programmer needs a variable that can be accessed throughout the class rather than only inside one method. Which category should be considered?","code":null,"choices":[{"letter":"A","text":"** Interface variable"},{"letter":"B","text":"** Block variable"},{"letter":"C","text":"** Class variable (or Instance variable)"},{"letter":"D","text":"** Local constant"}],"answer":"C","answerText":"Class variable (or Instance variable)","explanation":"Class fields and instance fields are declared at the class level outside any method, allowing them to be accessed across all methods in the class."},{"id":96,"partId":10,"partTitle":"Part 10: Variable Scopes (Block, Method, Instance, Class & Interface)","prompt":"Which statement best distinguishes a block variable from an interface variable?","code":null,"choices":[{"letter":"A","text":"** Block scope is narrower than interface variable scope"},{"letter":"B","text":"** Block scope is global throughout the package"},{"letter":"C","text":"** Interface scope is narrower than block scope"},{"letter":"D","text":"** Interface scope is method-only"}],"answer":"A","answerText":"Block scope is narrower than interface variable scope","explanation":"Block variables are strictly confined to their local enclosing braces, whereas interface variables (public static final) have public global visibility."},{"id":97,"partId":10,"partTitle":"Part 10: Variable Scopes (Block, Method, Instance, Class & Interface)","prompt":"A Java variable must be available beyond the method where it is declared. Which choice is least suitable for that requirement?","code":null,"choices":[{"letter":"A","text":"** Interface variable"},{"letter":"B","text":"** Class variable"},{"letter":"C","text":"** Instance variable"},{"letter":"D","text":"** Block variable"}],"answer":"D","answerText":"Block variable","explanation":"Block variables are destroyed when the block exits and cannot be accessed outside the declaring method."},{"id":98,"partId":10,"partTitle":"Part 10: Variable Scopes (Block, Method, Instance, Class & Interface)","prompt":"A developer wants a value available throughout a program and chooses between a block variable and an interface variable. Which choice better meets the requirement?","code":null,"choices":[{"letter":"A","text":"** The block variable"},{"letter":"B","text":"** The interface variable"},{"letter":"C","text":"** Both variables equally"},{"letter":"D","text":"** Neither variable applies"}],"answer":"B","answerText":"The interface variable","explanation":"Interface variables are implicitly public, static, and final, making them globally accessible constants throughout the entire program."},{"id":99,"partId":10,"partTitle":"Part 10: Variable Scopes (Block, Method, Instance, Class & Interface)","prompt":"A variable can be used inside its declaring method but not outside that method. Which conclusion is most reasonable?","code":null,"choices":[{"letter":"A","text":"** It is a local / block-scoped variable"},{"letter":"B","text":"** It is interface-scoped"},{"letter":"C","text":"** It is class-scoped"},{"letter":"D","text":"** It is instance-scoped"}],"answer":"A","answerText":"It is a local / block-scoped variable","explanation":"Local method variables are visible only within the body of the method in which they are declared."},{"id":100,"partId":10,"partTitle":"Part 10: Variable Scopes (Block, Method, Instance, Class & Interface)","prompt":"A programmer replaces an interface variable with a block variable while trying to preserve access throughout the program. What is the most likely result?","code":null,"choices":[{"letter":"A","text":"** Access becomes more limited and causes compile errors outside the block"},{"letter":"B","text":"** Access becomes completely unrestricted"},{"letter":"C","text":"** Access remains exactly unchanged"},{"letter":"D","text":"** Access automatically becomes class-wide"}],"answer":"A","answerText":"Access becomes more limited and causes compile errors outside the block","explanation":"Block variables restrict access strictly to their enclosing block, losing the global availability provided by public interface constants."},{"id":101,"partId":11,"partTitle":"Part 11: StringBuilder, String Immutability & Package Imports","prompt":"What is printed by this Java code?","code":"StringBuilder numbers = new StringBuilder(\"0123456789\");\nnumbers.delete(2, 8);\nnumbers.append(\"-\").insert(2, \"+\");\nSystem.out.println(numbers);","choices":[{"letter":"A","text":"** 01+89-"},{"letter":"B","text":"** 012+9-"},{"letter":"C","text":"** 012+-9"},{"letter":"D","text":"** 0123456789"}],"answer":"A","answerText":"01+89-","explanation":"1. delete(2, 8) removes indices 2 through 7 (\"234567\"), leaving \"0189\". 2. append(\"-\") results in \"0189-\". 3. insert(2, \"+\") places \"+\" at index 2, resulting in \"01+89-\"."},{"id":102,"partId":11,"partTitle":"Part 11: StringBuilder, String Immutability & Package Imports","prompt":"Which output lines are produced by this Java code?","code":"String s = new String(\"Hello\");\nString t = new String(s);\nif (\"Hello\".equals(t)) System.out.println(\"one\");\nif (t == s) System.out.println(\"two\");\nif (t.equals(s)) System.out.println(\"three\");\nif (t == \"Hello\") System.out.println(\"four\");\nif (s == \"Hello\") System.out.println(\"five\");","choices":[{"letter":"A","text":"** one only"},{"letter":"B","text":"** three only"},{"letter":"C","text":"** one and three"},{"letter":"D","text":"** two and four"},{"letter":"E","text":"** All five lines"}],"answer":"C","answerText":"one and three","explanation":"new String(...) creates separate heap objects. == compares reference identity (so t == s, t == \"Hello\", and s == \"Hello\" are all false). .equals() compares character content, so \"Hello\".equals(t) (\"one\") and t.equals(s) (\"three\") are true."},{"id":103,"partId":11,"partTitle":"Part 11: StringBuilder, String Immutability & Package Imports","prompt":"What happens when this Java code is compiled?","code":"String numbers = \"246A8\";\nint total = 0;\ntotal += Integer.valueOf(numbers.substring(1, 3));\ntotal += numbers.length();\nchar ch = numbers.charAt(3);\nSystem.out.println(total + \" \" + ch);","choices":[{"letter":"A","text":"** It prints 51 A"},{"letter":"B","text":"** It prints 46 A"},{"letter":"C","text":"** It prints 5 8"},{"letter":"D","text":"** It throws an exception"},{"letter":"E","text":"** The code does not compile"}],"answer":"A","answerText":"It prints 51 A","explanation":"substring(1, 3) gives \"46\". Integer.valueOf(\"46\") is 46. Adding length (5) makes total = 51. charAt(3) returns 'A'. Output is \"51 A\"."},{"id":104,"partId":11,"partTitle":"Part 11: StringBuilder, String Immutability & Package Imports","prompt":"Which statement about Java import statements is true?","code":null,"choices":[{"letter":"A","text":"** Unused imports prevent compilation"},{"letter":"B","text":"** Unused imports may be safely removed without affecting functionality"},{"letter":"C","text":"** Duplicate imports prevent compilation"},{"letter":"D","text":"** Missing classes can still be imported"}],"answer":"B","answerText":"Unused imports may be safely removed without affecting functionality","explanation":"Import statements tell the compiler where to locate type names; unused imports do not cause compilation errors or runtime overhead, and can be removed safely."},{"id":105,"partId":11,"partTitle":"Part 11: StringBuilder, String Immutability & Package Imports","prompt":"Which package is imported into every Java class by default without an explicit import statement?","code":null,"choices":[{"letter":"A","text":"** java.util"},{"letter":"B","text":"** java.system"},{"letter":"C","text":"** java.lang"},{"letter":"D","text":"** java.io"}],"answer":"C","answerText":"java.lang","explanation":"The java.lang package (containing String, System, Math, Object, Exception, etc.) is automatically imported by default into every Java source file."},{"id":106,"partId":11,"partTitle":"Part 11: StringBuilder, String Immutability & Package Imports","prompt":"Which loop executes a different number of times from the other three?","code":"// Loop A:\nfor (int i = 0; i < 5; i++) { }\n// Loop B:\nfor (int i = 1; i <= 5; i++) { }\n// Loop C:\nint k = 0; do { } while (k++ < 5);\n// Loop D:\nint k = 0; while (k++ < 5) { }","choices":[{"letter":"A","text":"** for (int i = 0; i < 5; i++)"},{"letter":"B","text":"** for (int i = 1; i <= 5; i++)"},{"letter":"C","text":"** int k = 0; do {} while (k++ < 5);"},{"letter":"D","text":"** int k = 0; while (k++ < 5) {}"}],"answer":"C","answerText":"int k = 0; do {} while (k++ < 5);","explanation":"A, B, and D execute their loop bodies exactly 5 times. The do-while loop (C) executes 6 times because the post-increment test allows an extra iteration."},{"id":107,"partId":11,"partTitle":"Part 11: StringBuilder, String Immutability & Package Imports","prompt":"For the string String numbers = \"246A8\"; what values are returned by numbers.substring(1, 3) and numbers.charAt(3), respectively?","code":"String numbers = \"246A8\";\nnumbers.substring(1, 3);\nnumbers.charAt(3);","choices":[{"letter":"A","text":"** \"24\" and '6'"},{"letter":"B","text":"** \"46\" and 'A'"},{"letter":"C","text":"** \"46\" and '8'"},{"letter":"D","text":"** \"6A\" and 'A'"}],"answer":"B","answerText":"\"46\" and 'A'","explanation":"substring(1, 3) extracts characters at index 1 and 2 ('4' and '6') producing \"46\". charAt(3) returns the character at index 3, which is 'A'."},{"id":108,"partId":11,"partTitle":"Part 11: StringBuilder, String Immutability & Package Imports","prompt":"What is printed by this Java code?","code":"String s = \"246A8\";\nint value = Integer.valueOf(s.substring(1, 3));\nSystem.out.println(value + s.charAt(3));","choices":[{"letter":"A","text":"** 46A"},{"letter":"B","text":"** 111"},{"letter":"C","text":"** 46 A"},{"letter":"D","text":"** The code does not compile"}],"answer":"B","answerText":"111","explanation":"s.substring(1, 3) is \"46\", parsed as int 46. s.charAt(3) is char 'A', which has ASCII value 65. Because int + char is numeric addition (not string concatenation), 46 + 65 evaluates to 111."},{"id":109,"partId":11,"partTitle":"Part 11: StringBuilder, String Immutability & Package Imports","prompt":"A Java class uses ArrayList without writing its fully qualified name, but it has no import statement for ArrayList. Which change is sufficient to allow the class to compile, assuming the class is otherwise correct?","code":null,"choices":[{"letter":"A","text":"** Add import java.util.ArrayList;"},{"letter":"B","text":"** Add import java.lang.ArrayList;"},{"letter":"C","text":"** Add import java.io.ArrayList;"},{"letter":"D","text":"** Add import java.system.ArrayList;"}],"answer":"A","answerText":"Add import java.util.ArrayList;","explanation":"ArrayList is located in the java.util package, so adding 'import java.util.ArrayList;' or 'import java.util.*;' allows the short class name to resolve."},{"id":110,"partId":11,"partTitle":"Part 11: StringBuilder, String Immutability & Package Imports","prompt":"What is printed by this Java code?","code":"String s = \"a\";\ns.concat(s);\ns.concat(\".\");\nSystem.out.println(s);","choices":[{"letter":"A","text":"** a"},{"letter":"B","text":"** aa."},{"letter":"C","text":"** aa"},{"letter":"D","text":"** a."}],"answer":"A","answerText":"a","explanation":"String objects in Java are immutable. Methods like s.concat() return a new String rather than modifying s in place. Since the returned values are not reassigned back to s, s remains \"a\"."},{"id":111,"partId":12,"partTitle":"Part 12: String Methods (substring, concat, indexOf) & Array Bounds","prompt":"Which statement about Java String objects is not true?","code":null,"choices":[{"letter":"A","text":"** A String can be created without an explicit constructor call."},{"letter":"B","text":"** String literals can be reused through the string pool."},{"letter":"C","text":"** A String variable can refer to a final object."},{"letter":"D","text":"** A String object's contents can be changed after creation."}],"answer":"D","answerText":"A String object's contents can be changed after creation.","explanation":"String objects in Java are immutable; once instantiated, their internal character sequences cannot be modified."},{"id":112,"partId":12,"partTitle":"Part 12: String Methods (substring, concat, indexOf) & Array Bounds","prompt":"Given the following code, which expression removes the space from the string?","code":"String g = \"Guinea Pig\";\nint i = g.indexOf(\" \");","choices":[{"letter":"A","text":"** g.substring(0, i) + g.substring(i);"},{"letter":"B","text":"** g.substring(0, i - 1) + g.substring(i);"},{"letter":"C","text":"** g.substring(0, i) + g.substring(i + 1);"},{"letter":"D","text":"** g.substring(0, i - 1) + g.substring(i + 1);"}],"answer":"C","answerText":"g.substring(0, i) + g.substring(i + 1);","explanation":"g.substring(0, i) gets characters before the space (\"Guinea\"), and g.substring(i + 1) gets characters after the space (\"Pig\"), omitting the space character at index i."},{"id":113,"partId":12,"partTitle":"Part 12: String Methods (substring, concat, indexOf) & Array Bounds","prompt":"What value does the expression \"a\" + 1 produce in Java?","code":null,"choices":[{"letter":"A","text":"** The integer 1"},{"letter":"B","text":"** The string \"a1\""},{"letter":"C","text":"** The string \"1a\""},{"letter":"D","text":"** A compilation error"}],"answer":"B","answerText":"The string \"a1\"","explanation":"When either operand of the + operator is a String, Java performs String concatenation, converting the integer 1 to \"1\" and returning \"a1\"."},{"id":114,"partId":12,"partTitle":"Part 12: String Methods (substring, concat, indexOf) & Array Bounds","prompt":"What is the value of i after this code executes?","code":"String g = \"Guinea Pig\";\nint i = g.indexOf(\" \");","choices":[{"letter":"A","text":"** 4"},{"letter":"B","text":"** 5"},{"letter":"C","text":"** 6"},{"letter":"D","text":"** 7"}],"answer":"C","answerText":"6","explanation":"Zero-based indexing: G(0), u(1), i(2), n(3), e(4), a(5), ' '(6). The space is located at index 6."},{"id":115,"partId":12,"partTitle":"Part 12: String Methods (substring, concat, indexOf) & Array Bounds","prompt":"What does String.concat() return when it is called on a String object?","code":null,"choices":[{"letter":"A","text":"** The original String after changing its contents"},{"letter":"B","text":"** A new String containing both sequences"},{"letter":"C","text":"** The index of the appended sequence"},{"letter":"D","text":"** A boolean indicating whether joining succeeded"}],"answer":"B","answerText":"A new String containing both sequences","explanation":"concat() creates and returns a brand-new String object representing the concatenation of the original string and the argument string."},{"id":116,"partId":12,"partTitle":"Part 12: String Methods (substring, concat, indexOf) & Array Bounds","prompt":"What is printed by this code?","code":"String g = \"Guinea Pig\";\nint i = g.indexOf(\" \");\nString ans = g.substring(0, i) + g.substring(i + 1);\nSystem.out.println(ans);","choices":[{"letter":"A","text":"** Guinea Pig"},{"letter":"B","text":"** GuineaPig"},{"letter":"C","text":"** Guinea  Pig"},{"letter":"D","text":"** PigGuinea"}],"answer":"B","answerText":"GuineaPig","explanation":"Concatenating \"Guinea\" (indices 0..5) and \"Pig\" (indices 7..9) without the space at index 6 prints \"GuineaPig\"."},{"id":117,"partId":12,"partTitle":"Part 12: String Methods (substring, concat, indexOf) & Array Bounds","prompt":"A programmer writes the following code: String s = \"cat\"; s.concat(\"dog\"); System.out.println(s); What is printed, and why?","code":"String s = \"cat\";\ns.concat(\"dog\");\nSystem.out.println(s);","choices":[{"letter":"A","text":"** cat, because concat does not modify the original String"},{"letter":"B","text":"** catdog, because concat permanently changes the original String"},{"letter":"C","text":"** dog, because concat replaces the original String"},{"letter":"D","text":"** Nothing, because concat always causes an exception"}],"answer":"A","answerText":"cat, because concat does not modify the original String","explanation":"Strings are immutable; s.concat(\"dog\") produces a new String \"catdog\" that is immediately discarded because it was not assigned to a variable."},{"id":118,"partId":12,"partTitle":"Part 12: String Methods (substring, concat, indexOf) & Array Bounds","prompt":"Which revision correctly stores the result of concatenating \"a\" and \"b\"?","code":"// Original:\nString s = \"a\";\ns.concat(\"b\");","choices":[{"letter":"A","text":"** String s = \"a\"; s = s.concat(\"b\");"},{"letter":"B","text":"** String s = \"a\"; s.append(\"b\");"},{"letter":"C","text":"** String s = \"a\"; s += concat(\"b\");"},{"letter":"D","text":"** String s = \"a\"; concat(s, \"b\");"}],"answer":"A","answerText":"String s = \"a\"; s = s.concat(\"b\");","explanation":"Reassigning the returned new String reference back to s (s = s.concat(\"b\"); or s += \"b\";) correctly saves the concatenated string."},{"id":119,"partId":12,"partTitle":"Part 12: String Methods (substring, concat, indexOf) & Array Bounds","prompt":"Which expression correctly references the first and last elements of a non-empty Java array named array?","code":null,"choices":[{"letter":"A","text":"** array[0] and array[array.length]"},{"letter":"B","text":"** array[0] and array[array.length()]"},{"letter":"C","text":"** array[0] and array[array.length - 1]"},{"letter":"D","text":"** array[1] and array[array.length - 1]"}],"answer":"C","answerText":"array[0] and array[array.length - 1]","explanation":"Java arrays are 0-indexed; the first element is at index 0 and the final element is at index array.length - 1."},{"id":120,"partId":12,"partTitle":"Part 12: String Methods (substring, concat, indexOf) & Array Bounds","prompt":"Given ArrayList<Integer> l = new ArrayList<>(); which expression returns the number of elements currently stored in l?","code":null,"choices":[{"letter":"A","text":"** l.capacity"},{"letter":"B","text":"** l.capacity()"},{"letter":"C","text":"** l.length"},{"letter":"D","text":"** l.length()"},{"letter":"E","text":"** l.size()"}],"answer":"E","answerText":"l.size()","explanation":"In Java Collections (including ArrayList), the size() method returns the count of elements currently stored."},{"id":121,"partId":13,"partTitle":"Part 13: Array Traversal, ArrayList Operations & Loop Semantics","prompt":"Which statement correctly describes the traversal order of a Java for-each loop over an array?","code":null,"choices":[{"letter":"A","text":"** It begins at index 0 and proceeds sequentially to the final index."},{"letter":"B","text":"** It begins at the final index and proceeds backward."},{"letter":"C","text":"** It begins at a random index."},{"letter":"D","text":"** It orders elements from largest to smallest value."}],"answer":"A","answerText":"It begins at index 0 and proceeds sequentially to the final index.","explanation":"An enhanced for-each loop over an array always iterates forward in index order from index 0 to length - 1."},{"id":122,"partId":13,"partTitle":"Part 13: Array Traversal, ArrayList Operations & Loop Semantics","prompt":"Which statement correctly compares a Java array's length with an ArrayList's size?","code":null,"choices":[{"letter":"A","text":"** Both use the length field."},{"letter":"B","text":"** Both use the size() method."},{"letter":"C","text":"** An array uses length; an ArrayList uses size()."},{"letter":"D","text":"** An array uses size(); an ArrayList uses length()."}],"answer":"C","answerText":"An array uses length; an ArrayList uses size().","explanation":"Arrays possess a public final field named length (no parentheses), while ArrayList instances provide a method named size()."},{"id":123,"partId":13,"partTitle":"Part 13: Array Traversal, ArrayList Operations & Loop Semantics","prompt":"For an array containing five elements, which expression references its last element?","code":null,"choices":[{"letter":"A","text":"** array[5]"},{"letter":"B","text":"** array[array.length]"},{"letter":"C","text":"** array[4] (or array[array.length - 1])"},{"letter":"D","text":"** array[1]"}],"answer":"C","answerText":"array[4] (or array[array.length - 1])","explanation":"For an array of length 5, valid indices are 0, 1, 2, 3, 4. The last element is at index 4."},{"id":124,"partId":13,"partTitle":"Part 13: Array Traversal, ArrayList Operations & Loop Semantics","prompt":"For an array containing five elements, what happens if code attempts to access array[5]?","code":"int[] array = new int[5];\nint last = array[5];","choices":[{"letter":"A","text":"** It returns the last element."},{"letter":"B","text":"** It throws ArrayIndexOutOfBoundsException at runtime."},{"letter":"C","text":"** It returns null."},{"letter":"D","text":"** It causes a compilation error."}],"answer":"B","answerText":"It throws ArrayIndexOutOfBoundsException at runtime.","explanation":"The maximum valid index for an array of length 5 is 4; accessing index 5 throws ArrayIndexOutOfBoundsException."},{"id":125,"partId":13,"partTitle":"Part 13: Array Traversal, ArrayList Operations & Loop Semantics","prompt":"A programmer writes int last = values[values.length - 1];. What condition must hold for this statement to execute successfully?","code":"int last = values[values.length - 1];","choices":[{"letter":"A","text":"** The array must contain at least one element."},{"letter":"B","text":"** The array must contain exactly one element."},{"letter":"C","text":"** The array must contain five elements."},{"letter":"D","text":"** The array must be an ArrayList."}],"answer":"A","answerText":"The array must contain at least one element.","explanation":"If values is empty (length 0), values.length - 1 evaluates to -1, which causes ArrayIndexOutOfBoundsException. Hence the array must contain at least 1 element."},{"id":126,"partId":13,"partTitle":"Part 13: Array Traversal, ArrayList Operations & Loop Semantics","prompt":"A programmer wants to process every element of an array from its final element toward its first element. Which approach is most appropriate?","code":null,"choices":[{"letter":"A","text":"** Use a for-each loop without changing it."},{"letter":"B","text":"** Use an indexed loop that decreases the index from length - 1 down to 0."},{"letter":"C","text":"** Use array.length as the first index."},{"letter":"D","text":"** Use an ArrayList's size() method."}],"answer":"B","answerText":"Use an indexed loop that decreases the index from length - 1 down to 0.","explanation":"Reverse traversal requires an index loop starting at array.length - 1, continuing while index >= 0, and decrementing index--."},{"id":127,"partId":13,"partTitle":"Part 13: Array Traversal, ArrayList Operations & Loop Semantics","prompt":"An ArrayList currently contains three elements but has internal capacity for ten. What should its element count be reported as?","code":null,"choices":[{"letter":"A","text":"** Three, obtained with size()"},{"letter":"B","text":"** Ten, obtained with size()"},{"letter":"C","text":"** Three, obtained with capacity()"},{"letter":"D","text":"** Ten, obtained with length()"}],"answer":"A","answerText":"Three, obtained with size()","explanation":"The size() method returns the logical count of items currently added (3), regardless of underlying buffer capacity."},{"id":128,"partId":13,"partTitle":"Part 13: Array Traversal, ArrayList Operations & Loop Semantics","prompt":"A loop must visit each element of an array exactly once in its normal left-to-right order, without modifying the array. Which loop design best fits this requirement?","code":null,"choices":[{"letter":"A","text":"** A for-each loop over the array"},{"letter":"B","text":"** A loop beginning at index 1"},{"letter":"C","text":"** A loop beginning at index array.length"},{"letter":"D","text":"** A loop decreasing from index 0"}],"answer":"A","answerText":"A for-each loop over the array","explanation":"Enhanced for-each loops are specifically designed for clean, read-only forward traversal over arrays and collections."},{"id":129,"partId":13,"partTitle":"Part 13: Array Traversal, ArrayList Operations & Loop Semantics","prompt":"Which statement correctly describes checked exceptions in Java?","code":null,"choices":[{"letter":"A","text":"** They must be handled with try-catch or declared with throws"},{"letter":"B","text":"** They may be handled or declared optionally"},{"letter":"C","text":"** They cannot be handled or declared"},{"letter":"D","text":"** They are handled only by the compiler"}],"answer":"A","answerText":"They must be handled with try-catch or declared with throws","explanation":"Java enforces the 'handle or declare' rule for all checked exceptions (subclasses of Exception excluding RuntimeException)."},{"id":130,"partId":13,"partTitle":"Part 13: Array Traversal, ArrayList Operations & Loop Semantics","prompt":"Which statement correctly describes runtime exceptions in Java?","code":null,"choices":[{"letter":"A","text":"** They must always be declared in the throws clause"},{"letter":"B","text":"** They may be handled or declared optionally (unchecked)"},{"letter":"C","text":"** They cannot be caught by any catch block"},{"letter":"D","text":"** They are handled only inside finally blocks"}],"answer":"B","answerText":"They may be handled or declared optionally (unchecked)","explanation":"Runtime exceptions (subclasses of RuntimeException) are unchecked: the compiler does not require you to catch or declare them."},{"id":131,"partId":14,"partTitle":"Part 14: Checked vs Unchecked Exceptions & try-catch Structure","prompt":"Which statement best distinguishes checked exceptions from runtime exceptions?","code":null,"choices":[{"letter":"A","text":"** Checked exceptions require handling or declaration; runtime exceptions do not"},{"letter":"B","text":"** Checked exceptions occur only during compilation"},{"letter":"C","text":"** Runtime exceptions require handling or declaration"},{"letter":"D","text":"** Runtime exceptions cannot be caught by programs"}],"answer":"A","answerText":"Checked exceptions require handling or declaration; runtime exceptions do not","explanation":"Checked exceptions are subject to compile-time checking requiring try-catch or throws; runtime exceptions are unchecked."},{"id":132,"partId":14,"partTitle":"Part 14: Checked vs Unchecked Exceptions & try-catch Structure","prompt":"What exception is thrown by this Java code?","code":"int[] nums = {1, 4, 6};\nObject p = nums;\nint[] two = (int[]) p;\nSystem.out.println(two[two.length]);","choices":[{"letter":"A","text":"** ClassCastException"},{"letter":"B","text":"** ArrayIndexOutOfBoundsException"},{"letter":"C","text":"** IllegalArgumentException"},{"letter":"D","text":"** NumberFormatException"},{"letter":"E","text":"** No exception is thrown"}],"answer":"B","answerText":"ArrayIndexOutOfBoundsException","explanation":"The cast (int[]) p succeeds. However, two.length is 3. Accessing two[3] exceeds the valid bounds (0..2), throwing ArrayIndexOutOfBoundsException."},{"id":133,"partId":14,"partTitle":"Part 14: Checked vs Unchecked Exceptions & try-catch Structure","prompt":"Why does the array access in this code throw an exception?","code":"int[] values = {1, 4, 6};\nSystem.out.println(values[values.length]);","choices":[{"letter":"A","text":"** The last valid index is one less than the length"},{"letter":"B","text":"** The array contains fewer than three elements"},{"letter":"C","text":"** The array cannot be stored in an Object variable"},{"letter":"D","text":"** The length field returns the first element's value"}],"answer":"A","answerText":"The last valid index is one less than the length","explanation":"Because Java uses 0-based indexing, values[values.length] tries to access an element past the end of the array."},{"id":134,"partId":14,"partTitle":"Part 14: Checked vs Unchecked Exceptions & try-catch Structure","prompt":"In the following code, what is the value of two.length before the print statement executes?","code":"int[] nums = {1, 4, 6};\nObject p = nums;\nint[] two = (int[]) p;\nSystem.out.println(two[two.length]);","choices":[{"letter":"A","text":"** 1"},{"letter":"B","text":"** 2"},{"letter":"C","text":"** 3"},{"letter":"D","text":"** 4"}],"answer":"C","answerText":"3","explanation":"nums was initialized with three elements ({1, 4, 6}), so its length property is 3."},{"id":135,"partId":14,"partTitle":"Part 14: Checked vs Unchecked Exceptions & try-catch Structure","prompt":"A Java array has length 3. Which index refers to its final element?","code":null,"choices":[{"letter":"A","text":"** Index 0"},{"letter":"B","text":"** Index 1"},{"letter":"C","text":"** Index 2"},{"letter":"D","text":"** Index 3"}],"answer":"C","answerText":"Index 2","explanation":"An array of length 3 contains indices 0, 1, and 2. Index 2 is the final element."},{"id":136,"partId":14,"partTitle":"Part 14: Checked vs Unchecked Exceptions & try-catch Structure","prompt":"A try statement has separate catch blocks for IllegalArgumentException and IndexOutOfBoundsException. In what order may these two catch blocks appear?","code":null,"choices":[{"letter":"A","text":"** Only IllegalArgumentException first"},{"letter":"B","text":"** Only IndexOutOfBoundsException first"},{"letter":"C","text":"** Either order is valid"},{"letter":"D","text":"** Neither order is permitted"}],"answer":"C","answerText":"Either order is valid","explanation":"IllegalArgumentException and IndexOutOfBoundsException are sibling classes inheriting from RuntimeException; neither is a subclass of the other, so they can appear in either order."},{"id":137,"partId":14,"partTitle":"Part 14: Checked vs Unchecked Exceptions & try-catch Structure","prompt":"Why can catch blocks for IllegalArgumentException and IndexOutOfBoundsException be declared in either order?","code":null,"choices":[{"letter":"A","text":"** Neither exception is a superclass or subclass of the other"},{"letter":"B","text":"** Both exceptions are checked exceptions"},{"letter":"C","text":"** Both exceptions are identical exception types"},{"letter":"D","text":"** Neither exception can be thrown at runtime"}],"answer":"A","answerText":"Neither exception is a superclass or subclass of the other","explanation":"Catch order matters only when one exception type is a subclass of another (where the subclass must be caught before the superclass)."},{"id":138,"partId":14,"partTitle":"Part 14: Checked vs Unchecked Exceptions & try-catch Structure","prompt":"Consider this Java code:\nWhat happens when this code is compiled?","code":"int a = 3, b = 0;\ntry {\n    System.out.print(3 % 0);\n} catch (IOException e) {\n    System.out.print(-1);\n} catch (ArithmeticException e) {\n    System.out.print(0);\n} finally {\n    System.out.print(\"done\");\n}","choices":[{"letter":"A","text":"** It prints 3done"},{"letter":"B","text":"** It prints -1done"},{"letter":"C","text":"** It prints 0done"},{"letter":"D","text":"** The code does not compile"}],"answer":"D","answerText":"The code does not compile","explanation":"IOException is a checked exception. The compiler detects that the try block has no statements that can possibly throw IOException, so catching IOException results in a compile-time error ('unreachable catch block')."},{"id":139,"partId":14,"partTitle":"Part 14: Checked vs Unchecked Exceptions & try-catch Structure","prompt":"Why does catching IOException in a try block containing only System.out.print(3 % 0) cause a compilation failure?","code":"try {\n    System.out.print(3 % 0);\n} catch (IOException e) {\n    // ...\n}","choices":[{"letter":"A","text":"** The try block cannot throw IOException (unreachable catch block)"},{"letter":"B","text":"** ArithmeticException must be caught before IOException"},{"letter":"C","text":"** finally blocks cannot follow IOException"},{"letter":"D","text":"** IOException is an unchecked exception"}],"answer":"A","answerText":"The try block cannot throw IOException (unreachable catch block)","explanation":"Java disallows catch blocks for checked exceptions that cannot be thrown by any statement in the corresponding try block."},{"id":140,"partId":14,"partTitle":"Part 14: Checked vs Unchecked Exceptions & try-catch Structure","prompt":"Which Java Throwable type is generally recommended not to catch directly in an application?","code":null,"choices":[{"letter":"A","text":"** CheckedException"},{"letter":"B","text":"** Exception"},{"letter":"C","text":"** RuntimeException"},{"letter":"D","text":"** Error"},{"letter":"E","text":"** IOException"}],"answer":"D","answerText":"Error","explanation":"Error represents severe abnormal conditions (such as OutOfMemoryError or StackOverflowError) from which a normal application cannot reasonably be expected to recover."},{"id":141,"partId":15,"partTitle":"Part 15: Exception Hierarchy, Arithmetic Errors, finally Blocks & Type Promotion","prompt":"In Java, which exception is normally associated with attempting an arithmetic operation such as division or remainder by zero on integer types?","code":null,"choices":[{"letter":"A","text":"** IOException"},{"letter":"B","text":"** ArithmeticException"},{"letter":"C","text":"** NullPointerException"},{"letter":"D","text":"** IndexOutOfBoundsException"},{"letter":"E","text":"** ClassCastException"}],"answer":"B","answerText":"ArithmeticException","explanation":"Integer division or modulo by zero in Java throws an ArithmeticException at runtime."},{"id":142,"partId":15,"partTitle":"Part 15: Exception Hierarchy, Arithmetic Errors, finally Blocks & Type Promotion","prompt":"In the code below, assume the IOException catch block has been removed and the expression is changed to 3 % 1: What is printed?","code":"try {\n    System.out.print(3 % 1);\n} catch (ArithmeticException e) {\n    System.out.print(0);\n} finally {\n    System.out.print(\"done\");\n}","choices":[{"letter":"A","text":"** 0done"},{"letter":"B","text":"** 1done"},{"letter":"C","text":"** 3done"},{"letter":"D","text":"** done1"},{"letter":"E","text":"** Nothing is printed"}],"answer":"A","answerText":"0done","explanation":"3 % 1 evaluates to 0, which is printed in the try block. No exception occurs. The finally block executes next, printing \"done\", resulting in \"0done\"."},{"id":143,"partId":15,"partTitle":"Part 15: Exception Hierarchy, Arithmetic Errors, finally Blocks & Type Promotion","prompt":"In the following corrected Java structure, what is the purpose and guarantee of the finally block?","code":"try {\n    // statement that may fail\n} catch (ArithmeticException e) {\n    // exception handling\n} finally {\n    System.out.print(\"done\");\n}","choices":[{"letter":"A","text":"** It runs only when no exception occurs"},{"letter":"B","text":"** It runs only when an arithmetic exception occurs"},{"letter":"C","text":"** It executes after the try-catch blocks whether an exception was thrown or not"},{"letter":"D","text":"** It prevents every exception from propagating"}],"answer":"C","answerText":"It executes after the try-catch blocks whether an exception was thrown or not","explanation":"The finally block is guaranteed to execute upon leaving the try-catch structure, regardless of whether an exception was thrown or caught."},{"id":144,"partId":15,"partTitle":"Part 15: Exception Hierarchy, Arithmetic Errors, finally Blocks & Type Promotion","prompt":"Why is the IOException catch clause problematic in a try block that contains only System.out.print(3 % 0)?","code":null,"choices":[{"letter":"A","text":"** IOException is an unchecked exception"},{"letter":"B","text":"** The try block cannot throw IOException"},{"letter":"C","text":"** ArithmeticException must be caught first"},{"letter":"D","text":"** finally blocks cannot follow catch blocks"},{"letter":"E","text":"** IOException cannot be used in Java"}],"answer":"B","answerText":"The try block cannot throw IOException","explanation":"The Java compiler checks that checked exceptions declared in a catch clause can actually be thrown by the code in the try block."},{"id":145,"partId":15,"partTitle":"Part 15: Exception Hierarchy, Arithmetic Errors, finally Blocks & Type Promotion","prompt":"Suppose the IOException catch clause is removed from the displayed program, while 3 % 0 remains in the try block. Which output is produced?","code":"try {\n    System.out.print(3 % 0);\n} catch (ArithmeticException e) {\n    System.out.print(0);\n} finally {\n    System.out.print(\"done\");\n}","choices":[{"letter":"A","text":"** 3 followed by done"},{"letter":"B","text":"** -1 followed by done"},{"letter":"C","text":"** 0 followed by done (0done)"},{"letter":"D","text":"** Only done"},{"letter":"E","text":"** No output at all"}],"answer":"C","answerText":"0 followed by done (0done)","explanation":"3 % 0 throws ArithmeticException, caught by the catch block which prints '0'. The finally block executes next and prints 'done', resulting in '0done'."},{"id":146,"partId":15,"partTitle":"Part 15: Exception Hierarchy, Arithmetic Errors, finally Blocks & Type Promotion","prompt":"A programmer wants the remainder operation to avoid throwing ArithmeticException. Which replacement for 3 % 0 avoids that exception?","code":null,"choices":[{"letter":"A","text":"** 3 % 1"},{"letter":"B","text":"** 3 / 0"},{"letter":"C","text":"** 0 / 0"},{"letter":"D","text":"** 3 % 0"}],"answer":"A","answerText":"3 % 1","explanation":"3 % 1 computes 3 modulo 1 = 0 without dividing by zero, executing without throwing ArithmeticException."},{"id":147,"partId":15,"partTitle":"Part 15: Exception Hierarchy, Arithmetic Errors, finally Blocks & Type Promotion","prompt":"A Java program catches both IOException and ArithmeticException, but the try block currently performs only a remainder-by-zero operation. What is the best correction if the program is intended to handle the arithmetic failure and still compile?","code":null,"choices":[{"letter":"A","text":"** Remove the IOException catch block"},{"letter":"B","text":"** Remove the ArithmeticException catch block"},{"letter":"C","text":"** Move finally before the try block"},{"letter":"D","text":"** Change ArithmeticException to Error"},{"letter":"E","text":"** Change the remainder operation to text output"}],"answer":"A","answerText":"Remove the IOException catch block","explanation":"Removing the unreachable checked IOException catch block allows the code to compile and handle ArithmeticException cleanly."},{"id":148,"partId":15,"partTitle":"Part 15: Exception Hierarchy, Arithmetic Errors, finally Blocks & Type Promotion","prompt":"Which statement best describes the relationship between ArithmeticException and the Java exception hierarchy?","code":null,"choices":[{"letter":"A","text":"** It is a checked exception and must always be declared"},{"letter":"B","text":"** It is an unchecked RuntimeException and can be caught explicitly"},{"letter":"C","text":"** It is an Error and cannot be caught"},{"letter":"D","text":"** It is unrelated to arithmetic operations"},{"letter":"E","text":"** It can be caught only by IOException"}],"answer":"B","answerText":"It is an unchecked RuntimeException and can be caught explicitly","explanation":"ArithmeticException extends RuntimeException; it is unchecked (not required to be declared in throws), but can be caught by a catch block."},{"id":149,"partId":15,"partTitle":"Part 15: Exception Hierarchy, Arithmetic Errors, finally Blocks & Type Promotion","prompt":"What happens when this Java code is compiled and run?","code":"byte a = 40, b = 50;\nbyte sum = (byte) a + b;\nSystem.out.println(sum);","choices":[{"letter":"A","text":"** It prints 10."},{"letter":"B","text":"** It prints 40."},{"letter":"C","text":"** It prints 90."},{"letter":"D","text":"** It does not compile."}],"answer":"D","answerText":"It does not compile.","explanation":"Cast operator (byte) has higher precedence than addition (+). Thus, (byte) a + b casts only 'a' to byte, then evaluates the binary addition as int (int + byte = int). Assigning that int result to byte sum causes a compile error ('incompatible types: possible lossy conversion from int to byte'). Correct: (byte) (a + b)."},{"id":150,"partId":15,"partTitle":"Part 15: Exception Hierarchy, Arithmetic Errors, finally Blocks & Type Promotion","prompt":"Why does the statement byte sum = (byte) a + b; fail to compile when both a and b are bytes?","code":"byte a = 40, b = 50;\nbyte sum = (byte) a + b;","choices":[{"letter":"A","text":"** The addition promotes the operands to int, resulting in an int sum that cannot be assigned to byte without parenthesized casting."},{"letter":"B","text":"** The addition converts both values to double."},{"letter":"C","text":"** The cast changes both variables to String."},{"letter":"D","text":"** The byte type cannot store the value 90."}],"answer":"A","answerText":"The addition promotes the operands to int, resulting in an int sum that cannot be assigned to byte without parenthesized casting.","explanation":"Java binary arithmetic operators automatically promote byte and short operands to int. Without enclosing parentheses around the addition (byte)(a + b), the expression evaluates to an int."}]}};